using UnityEngine;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using FPS; // EnemyHealth
namespace FPS
{

    // Système de dash directionnel
    // Permet au joueur de dasher dans la direction de la caméra et de tuer les ennemis sur son passage
    public class DashSystem : MonoBehaviour
    {
        [Header("Dash Settings")]
        [Tooltip("Vitesse du dash")]
        [SerializeField] private float dashSpeed = 25f;

        [Tooltip("Durée du dash en secondes")]
        [SerializeField] private float dashDuration = 0.4f;

        [Tooltip("Courbe de vitesse du dash (X = temps normalisé 0-1, Y = multiplicateur de vitesse)")]
        [SerializeField] private AnimationCurve dashSpeedCurve = AnimationCurve.EaseInOut(0f, 1f, 1f, 0.3f);

        [Header("Dash Charge Settings")]
        [Tooltip("Activer la régénération automatique du dash (désactiver pour forcer le kill d'ennemis)")]
        [SerializeField] private bool autoRegenerate = false;

        [Tooltip("Cooldown entre chaque dash en secondes (uniquement si autoRegenerate est activé)")]
        [SerializeField] private float dashCooldown = 1.5f;

        [Tooltip("Nombre d'ennemis spéciaux à tuer pour remplir complètement la barre de dash")]
        [SerializeField] private int enemiesRequiredForFullCharge = 3;

        [Tooltip("Charge de dash actuelle (0 à 1)")]
        [SerializeField] private float currentDashCharge = 1f;

        [Tooltip("Rayon de détection des ennemis pendant le dash")]
        [SerializeField] private float dashHitRadius = 1.0f;

        [Tooltip("Dégâts infligés aux ennemis touchés")]
        [SerializeField] private float dashDamage = 9999f;

        [Tooltip("LayerMask pour détecter les ennemis")]
        [SerializeField] private LayerMask enemyMask = ~0;

        [Header("Collision Settings")]
        [Tooltip("Angle maximum (en degrés) entre la direction du dash et la surface pour continuer le dash. Au-delà, le dash s'arrête.")]
        [SerializeField] private float maxCollisionAngle = 45f;

        [Tooltip("LayerMask pour les obstacles qui peuvent arrêter le dash")]
        [SerializeField] private LayerMask obstacleMask = ~0;

        [Tooltip("Distance de détection des obstacles devant le joueur")]
        [SerializeField] private float obstacleCheckDistance = 0.5f;

        [Header("FOV Settings")]
        [Tooltip("FOV pendant le dash")]
        [SerializeField] private float dashFOV = 90f;

        [Tooltip("Vitesse de transition du FOV")]
        [SerializeField] private float fovTransitionSpeed = 15f;

        [Header("Momentum Settings")]
        [Tooltip("Conserver l'énergie cinétique à la sortie du dash")]
        [SerializeField] private bool conserveMomentum = true;

        [Tooltip("Pourcentage du momentum du dash à conserver (0 à 1)")]
        [SerializeField] private float momentumRetention = 0.8f;

        [Header("References")]
        [SerializeField] private FPSPlayerController playerController;
        [SerializeField] private FPSMovement fpsMovement;
        [SerializeField] private Transform cameraTransform;
        [SerializeField] private SoundPlayer sound;

        private Camera playerCamera;
        private float defaultFOV;
        private float targetFOV;

        public bool isDashing = false;
        private float dashTimer = 0f;
        private float cooldownTimer = 0f;

        private CharacterController characterController;

        private static System.Collections.Generic.HashSet<GameObject> enemiesKilledByDash = new System.Collections.Generic.HashSet<GameObject>();

        // Runtime
        private Vector3 directionalDashDir;
        private Vector3 lastDashPosition;
        private readonly HashSet<GameObject> _hitThisDash = new HashSet<GameObject>();
        private static readonly RaycastHit[] _hitBuffer = new RaycastHit[32];

        private void Start()
        {
            if (playerController == null)
            {
                playerController = GetComponent<FPSPlayerController>();
                if (playerController == null)
                {
                    return;
                }
            }

            if (fpsMovement == null)
            {
                fpsMovement = GetComponent<FPSMovement>();
            }

            if (cameraTransform == null)
            {
                cameraTransform = playerController.CameraTransform;
                if (cameraTransform == null)
                {
                    return;
                }
            }

            if (cameraTransform != null)
            {
                playerCamera = cameraTransform.GetComponent<Camera>();
                if (playerCamera != null)
                {
                    defaultFOV = playerCamera.fieldOfView;
                    targetFOV = defaultFOV;
                }
            }

            characterController = playerController.Controller;
        }

        private void Update()
        {
            // Mise à jour du cooldown
            if (autoRegenerate && cooldownTimer < dashCooldown)
            {
                cooldownTimer += Time.deltaTime;

                // Régénération automatique de la charge
                if (cooldownTimer >= dashCooldown && currentDashCharge < 1f)
                {
                    currentDashCharge = 1f;
                }
            }

            // Empêcher le dash pendant un stun
            var stunComp = GetComponent<PlayerStunAutoFire>();
            bool isStunned = stunComp != null && stunComp.IsStunned;

            // Gestion du dash
            if (isDashing)
            {
                HandleDash();
            }
            else
            {
                bool hasCharge = currentDashCharge >= 1f;
                bool cooldownReady = autoRegenerate ? (cooldownTimer >= dashCooldown) : true;

                if (!isStunned && Input.GetMouseButtonDown(1) && hasCharge && cooldownReady)
                {
                    StartDirectionalDash();
                }
            }

            // Gestion du FOV
            UpdateFOV();
        }

        private void FixedUpdate()
        {
            if (!isDashing || characterController == null) return;

            // Vérifier les obstacles devant le joueur
            if (CheckObstacleCollision())
            {
                EndDash();
                return;
            }

            float dashProgress = Mathf.Clamp01(dashTimer / dashDuration);

            // Évaluer la courbe pour obtenir le multiplicateur de vitesse
            float speedMultiplier = dashSpeedCurve.Evaluate(dashProgress);

            // Mouvement en ligne droite selon la direction de dash avec la courbe appliquée
            Vector3 dashMovement = directionalDashDir * (dashSpeed * speedMultiplier * Time.fixedDeltaTime);

            Vector3 currentPos = transform.position;
            Vector3 nextPos = currentPos + dashMovement;
            Vector3 seg = nextPos - lastDashPosition;
            float segLen = seg.magnitude;
            if (segLen > 0.0001f)
            {
                int hits = Physics.SphereCastNonAlloc(
                    lastDashPosition,
                    dashHitRadius,
                    seg.normalized,
                    _hitBuffer,
                    segLen,
                    enemyMask,
                    QueryTriggerInteraction.Ignore
                );
                for (int i = 0; i < hits; i++)
                {
                    var h = _hitBuffer[i];
                    if (h.collider == null) continue;
                    var enemyHealth = h.collider.GetComponentInParent<EnemyHealth>() ?? h.collider.GetComponent<EnemyHealth>();
                    if (enemyHealth == null) continue;

                    var enemyRoot = enemyHealth.transform.root.gameObject;
                    if (_hitThisDash.Contains(enemyRoot)) continue;
                    _hitThisDash.Add(enemyRoot);

                    // Si c'est un ennemi électrique -> stun le joueur (auto-fire)
                    var electric = h.collider.GetComponentInParent<Ennemies.Effect.ElectricEnnemis>() ?? h.collider.GetComponent<Ennemies.Effect.ElectricEnnemis>();
                    if (electric != null)
                    {
                        var playerStun = GetComponent<PlayerStunAutoFire>();
                        if (playerStun == null) playerStun = gameObject.AddComponent<PlayerStunAutoFire>();
                        if (electric.OverrideAutoFireInterval)
                            playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                        else
                            playerStun.ApplyStun(electric.StunDuration);

                        // Arrêter le dash immédiatement à cause du stun électrique
                        EndDash();
                        return;
                    }

                    // Marquer comme kill par dash si le coup sera létal
                    bool willDie = enemyHealth.CurrentHealth <= dashDamage;
                    if (willDie)
                    {
                        enemiesKilledByDash.Add(enemyRoot);
                        StartCoroutine(CleanupEnemyTracking(enemyRoot));

                        // Désactiver immédiatement les collisions pour permettre le dash à travers
                        DisableEnemyCollisions(enemyRoot);
                    }

                    // Appliquer dégâts
                    // enemyHealth.TakeDamage(dashDamage, "Dash");
                    enemyHealth.TakeDamage(new DamageInfo(dashDamage, "Dash", DamageType.Dash));
                }
            }

            lastDashPosition = nextPos;
            characterController.Move(dashMovement);
            Debug.DrawRay(transform.position, directionalDashDir * 3f, Color.cyan, 0.05f);
        }

        private void StartDirectionalDash()
        {
            Vector3 fwd;
            if (playerCamera != null)
            {
                Ray aimRay = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
                fwd = aimRay.direction;
            }
            else if (cameraTransform != null)
            {
                fwd = cameraTransform.forward;
            }
            else
            {
                fwd = transform.forward;
            }

            if(sound != null)
            {
                sound.PlayOneShot("Dash");
            }

            directionalDashDir = fwd.normalized;

            currentDashCharge = 0f;

            // Mettre la vitesse de mouvement au maximum
            if (fpsMovement != null)
            {
                fpsMovement.SetSpeedToMax();
            }

            // Init timers/état
            isDashing = true;
            dashTimer = 0f;
            targetFOV = dashFOV;
            lastDashPosition = transform.position;
            _hitThisDash.Clear();
        }

        private void HandleDash()
        {
            dashTimer += Time.deltaTime;

            if (dashTimer >= dashDuration)
            {
                EndDash();
            }
        }

        // Vérifie si le dash doit être arrêté par une collision avec un obstacle à mauvais angle
        private bool CheckObstacleCollision()
        {
            // Raycast dans la direction du dash pour détecter les obstacles
            RaycastHit hit;
            float checkDistance = obstacleCheckDistance;

            // SphereCast pour détecter les obstacles devant le joueur avec un rayon similaire au dashHitRadius
            if (Physics.SphereCast(
                transform.position,
                dashHitRadius * 0.8f, // Légèrement plus petit pour éviter les faux positifs
                directionalDashDir,
                out hit,
                checkDistance,
                obstacleMask,
                QueryTriggerInteraction.Ignore))
            {
                // Ignorer si c'est un ennemi (ils sont gérés séparément)
                var enemyHealth = hit.collider.GetComponentInParent<EnemyHealth>() ?? hit.collider.GetComponent<EnemyHealth>();
                if (enemyHealth != null)
                {
                    return false; // Ne pas arrêter le dash pour les ennemis
                }

                // Calculer l'angle entre la direction du dash et la normale de la surface
                float angle = Vector3.Angle(directionalDashDir, -hit.normal);

                // Debug visuel
                Debug.DrawRay(hit.point, hit.normal * 2f, Color.red, 0.1f);
                Debug.DrawRay(hit.point, directionalDashDir * 2f, Color.yellow, 0.1f);

                // Si l'angle est trop abrupt (surface trop perpendiculaire à la direction du dash)
                if (angle > maxCollisionAngle)
                {
                    Debug.Log($"[DashSystem] Dash arrêté par collision ! Angle: {angle:F1}° (max: {maxCollisionAngle}°)");
                    return true; // Arrêter le dash
                }
            }

            return false; // Continuer le dash
        }


        // Désactive toutes les collisions d'un ennemi pour permettre au dash de passer à travers.
        private void DisableEnemyCollisions(GameObject enemy)
        {

            Collider[] colliders = enemy.GetComponentsInChildren<Collider>();
            foreach (Collider col in colliders)
            {
                col.enabled = false;
            }

            // Désactiver également le rigidbody pour éviter les interactions physiques
            Rigidbody rb = enemy.GetComponent<Rigidbody>();
            if (rb != null)
            {
                rb.isKinematic = true;
                rb.detectCollisions = false;
            }

            Rigidbody[] childRbs = enemy.GetComponentsInChildren<Rigidbody>();
            foreach (Rigidbody childRb in childRbs)
            {
                childRb.isKinematic = true;
                childRb.detectCollisions = false;
            }
        }

        private System.Collections.IEnumerator CleanupEnemyTracking(GameObject enemy)
        {
            yield return new WaitForSeconds(2f);
            if (enemy == null)
            {
                // L'ennemi a bien été détruit, on peut le retirer du tracking
                enemiesKilledByDash.Remove(enemy);
            }
        }

        // Vérifie si un ennemi a été tué par le dash
        public static bool WasKilledByDash(GameObject enemy)
        {
            return enemiesKilledByDash.Contains(enemy);
        }

        private void EndDash()
        {
            // Appliquer le momentum de sortie si activé
            if (conserveMomentum && fpsMovement != null)
            {
                // Calculer le momentum basé sur la vitesse du dash
                Vector3 dashMomentum = directionalDashDir * dashSpeed * momentumRetention;
                fpsMovement.ApplyExternalMomentum(dashMomentum);

                Debug.Log($"[DashSystem] Momentum conservé: {dashMomentum.magnitude:F1} m/s dans la direction {directionalDashDir}");
            }

            isDashing = false;
            dashTimer = 0f;
            cooldownTimer = 0f;
            targetFOV = defaultFOV;
        }

        private void UpdateFOV()
        {
            if (playerCamera != null)
            {
                playerCamera.fieldOfView = Mathf.Lerp(
                    playerCamera.fieldOfView,
                    targetFOV,
                    Time.deltaTime * fovTransitionSpeed
                );
            }
        }

        public bool CanDash => currentDashCharge >= 1f && !isDashing && (autoRegenerate ? cooldownTimer >= dashCooldown : true);

        public float DashCooldownProgress => Mathf.Clamp01(cooldownTimer / dashCooldown);

        public float CurrentDashCharge => currentDashCharge;

        // Appelé quand un ennemi spécial (DashEnergyEnemy) est tué
        public void OnDashEnemyKilled(float energyAmount)
        {
            float oldCharge = currentDashCharge;

            // Calculer l'énergie par ennemi (1 / nombre d'ennemis requis)
            float energyPerEnemy = 1f / Mathf.Max(1, enemiesRequiredForFullCharge);

            // Ajouter l'énergie (multipliée par le montant configuré sur l'ennemi)
            currentDashCharge = Mathf.Clamp01(currentDashCharge + (energyPerEnemy * energyAmount));

            Debug.Log($"[DashSystem] Dash rechargé! {oldCharge:P0} → {currentDashCharge:P0} (+{energyPerEnemy * energyAmount:P0})");
        }
    }
}

using UnityEngine;
using System.Collections.Generic;
using System.Runtime.CompilerServices;
using FPS; // EnemyHealth
namespace FPS
{

    // Système de dash directionnel
    // Permet au joueur de dasher dans la direction de la caméra et de tuer les ennemis sur son passage
    public class DashSystem : MonoBehaviour
    {
        [Header("Dash Settings")]
        [Tooltip("Vitesse du dash")]
        [SerializeField] private float dashSpeed = 25f;

        [Tooltip("Durée du dash en secondes")]
        [SerializeField] private float dashDuration = 0.4f;

        [Tooltip("Courbe de vitesse du dash (X = temps normalisé 0-1, Y = multiplicateur de vitesse)")]
        [SerializeField] private AnimationCurve dashSpeedCurve = AnimationCurve.EaseInOut(0f, 1f, 1f, 0.3f);

        [Header("Dash Charge Settings")]
        [Tooltip("Activer la régénération automatique du dash (désactiver pour forcer le kill d'ennemis)")]
        [SerializeField] private bool autoRegenerate = false;

        [Tooltip("Cooldown entre chaque dash en secondes (uniquement si autoRegenerate est activé)")]
        [SerializeField] private float dashCooldown = 1.5f;

        [Tooltip("Nombre d'ennemis spéciaux à tuer pour remplir complètement la barre de dash")]
        [SerializeField] private int enemiesRequiredForFullCharge = 3;

        [Tooltip("Charge de dash actuelle (0 à 1)")]
        [SerializeField] private float currentDashCharge = 1f;

        [Tooltip("Rayon de détection des ennemis pendant le dash")]
        [SerializeField] private float dashHitRadius = 1.0f;

        [Tooltip("Dégâts infligés aux ennemis touchés")]
        [SerializeField] private float dashDamage = 9999f;

        [Tooltip("LayerMask pour détecter les ennemis")]
        [SerializeField] private LayerMask enemyMask = ~0;

        [Header("Collision Settings")]
        [Tooltip("Angle maximum (en degrés) entre la direction du dash et la surface pour continuer le dash. Au-delà, le dash s'arrête.")]
        [SerializeField] private float maxCollisionAngle = 45f;

        [Tooltip("LayerMask pour les obstacles qui peuvent arrêter le dash")]
        [SerializeField] private LayerMask obstacleMask = ~0;

        [Tooltip("Distance de détection des obstacles devant le joueur")]
        [SerializeField] private float obstacleCheckDistance = 0.5f;

        [Header("FOV Settings")]
        [Tooltip("FOV pendant le dash")]
        [SerializeField] private float dashFOV = 90f;

        [Tooltip("Vitesse de transition du FOV")]
        [SerializeField] private float fovTransitionSpeed = 15f;

        [Header("Momentum Settings")]
        [Tooltip("Conserver l'énergie cinétique à la sortie du dash")]
        [SerializeField] private bool conserveMomentum = true;

        [Tooltip("Pourcentage du momentum du dash à conserver (0 à 1)")]
        [SerializeField] private float momentumRetention = 0.8f;

        [Header("References")]
        [SerializeField] private FPSPlayerController playerController;
        [SerializeField] private FPSMovement fpsMovement;
        [SerializeField] private Transform cameraTransform;
        [SerializeField] private SoundPlayer sound;

        private Camera playerCamera;
        private float defaultFOV;
        private float targetFOV;

        public bool isDashing = false;
        private float dashTimer = 0f;
        private float cooldownTimer = 0f;

        private Rigidbody rb;

        private static System.Collections.Generic.HashSet<GameObject> enemiesKilledByDash = new System.Collections.Generic.HashSet<GameObject>();

        // Runtime
        private Vector3 directionalDashDir;
        private Vector3 lastDashPosition;
        private readonly HashSet<GameObject> _hitThisDash = new HashSet<GameObject>();
        private static readonly RaycastHit[] _hitBuffer = new RaycastHit[32];

        private void Start()
        {
            if (playerController == null)
            {
                playerController = GetComponent<FPSPlayerController>();
                if (playerController == null)
                {
                    return;
                }
            }

            if (fpsMovement == null)
            {
                fpsMovement = GetComponent<FPSMovement>();
            }

            if (cameraTransform == null)
            {
                cameraTransform = playerController.CameraTransform;
                if (cameraTransform == null)
                {
                    return;
                }
            }

            if (cameraTransform != null)
            {
                playerCamera = cameraTransform.GetComponent<Camera>();
                if (playerCamera != null)
                {
                    defaultFOV = playerCamera.fieldOfView;
                    targetFOV = defaultFOV;
                }
            }

            rb = fpsMovement != null ? fpsMovement.Rb : GetComponent<Rigidbody>();

            if (rb == null)
            {
                rb = GetComponent<Rigidbody>();
                Debug.LogWarning("[DashSystem] Rigidbody obtenu directement car fpsMovement.Rb était null");
            }

            if (rb == null)
            {
                Debug.LogError("[DashSystem] Rigidbody non trouvé! Le dash ne fonctionnera pas.");
            }
        }

        private void Update()
        {
            // Mise à jour du cooldown
            if (autoRegenerate && cooldownTimer < dashCooldown)
            {
                cooldownTimer += Time.deltaTime;

                // Régénération automatique de la charge
                if (cooldownTimer >= dashCooldown && currentDashCharge < 1f)
                {
                    currentDashCharge = 1f;
                }
            }

            // Empêcher le dash pendant un stun
            var stunComp = GetComponent<PlayerStunAutoFire>();
            bool isStunned = stunComp != null && stunComp.IsStunned;

            // Gestion du dash
            if (isDashing)
            {
                HandleDash();
            }
            else
            {
                bool hasCharge = currentDashCharge >= 1f;
                bool cooldownReady = autoRegenerate ? (cooldownTimer >= dashCooldown) : true;

                if (!isStunned && Input.GetMouseButtonDown(1) && hasCharge && cooldownReady)
                {
                    StartDirectionalDash();
                }
            }

            // Gestion du FOV
            UpdateFOV();
        }

        private void FixedUpdate()
        {
            if (!isDashing || rb == null) return;

            // Vérifier les obstacles devant le joueur
            if (CheckObstacleCollision())
            {
                EndDash();
                return;
            }

            float dashProgress = Mathf.Clamp01(dashTimer / dashDuration);

            // Évaluer la courbe pour obtenir le multiplicateur de vitesse
            float speedMultiplier = dashSpeedCurve.Evaluate(dashProgress);

            // Mouvement en ligne droite selon la direction de dash avec la courbe appliquée
            Vector3 dashMovement = directionalDashDir * (dashSpeed * speedMultiplier * Time.fixedDeltaTime);

            Vector3 currentPos = transform.position;
            Vector3 nextPos = currentPos + dashMovement;
            Vector3 seg = nextPos - lastDashPosition;
            float segLen = seg.magnitude;
            if (segLen > 0.0001f)
            {
                int hits = Physics.SphereCastNonAlloc(
                    lastDashPosition,
                    dashHitRadius,
                    seg.normalized,
                    _hitBuffer,
                    segLen,
                    enemyMask,
                    QueryTriggerInteraction.Ignore
                );
                for (int i = 0; i < hits; i++)
                {
                    var h = _hitBuffer[i];
                    if (h.collider == null) continue;
                    var enemyHealth = h.collider.GetComponentInParent<EnemyHealth>() ?? h.collider.GetComponent<EnemyHealth>();
                    if (enemyHealth == null) continue;

                    var enemyRoot = enemyHealth.transform.root.gameObject;
                    if (_hitThisDash.Contains(enemyRoot)) continue;
                    _hitThisDash.Add(enemyRoot);

                    // Si c'est un ennemi électrique -> stun le joueur (auto-fire)
                    var electric = h.collider.GetComponentInParent<Ennemies.Effect.ElectricEnnemis>() ?? h.collider.GetComponent<Ennemies.Effect.ElectricEnnemis>();
                    if (electric != null)
                    {
                        var playerStun = GetComponent<PlayerStunAutoFire>();
                        if (playerStun == null) playerStun = gameObject.AddComponent<PlayerStunAutoFire>();
                        if (electric.OverrideAutoFireInterval)
                            playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                        else
                            playerStun.ApplyStun(electric.StunDuration);

                        // Arrêter le dash immédiatement à cause du stun électrique
                        EndDash();
                        return;
                    }

                    // Marquer comme kill par dash si le coup sera létal
                    bool willDie = enemyHealth.CurrentHealth <= dashDamage;
                    if (willDie)
                    {
                        enemiesKilledByDash.Add(enemyRoot);
                        StartCoroutine(CleanupEnemyTracking(enemyRoot));

                        // Désactiver immédiatement les collisions pour permettre le dash à travers
                        DisableEnemyCollisions(enemyRoot);
                    }

                    // Appliquer dégâts
                    // enemyHealth.TakeDamage(dashDamage, "Dash");
                    enemyHealth.TakeDamage(new DamageInfo(dashDamage, "Dash", DamageType.Dash));
                }
            }

            lastDashPosition = nextPos;
            rb.MovePosition(rb.position + dashMovement);
            Debug.DrawRay(transform.position, directionalDashDir * 3f, Color.cyan, 0.05f);
        }

        private void StartDirectionalDash()
        {
            Vector3 fwd;
            if (playerCamera != null)
            {
                Ray aimRay = playerCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
                fwd = aimRay.direction;
            }
            else if (cameraTransform != null)
            {
                fwd = cameraTransform.forward;
            }
            else
            {
                fwd = transform.forward;
            }

            if(sound != null)
            {
                sound.PlayOneShot("Dash");
            }

            directionalDashDir = fwd.normalized;

            currentDashCharge = 0f;

            // Mettre la vitesse de mouvement au maximum et désactiver le mouvement normal
            if (fpsMovement != null)
            {
                fpsMovement.SetSpeedToMax();
                fpsMovement.DisableMovement();
            }

            // Init timers/état
            isDashing = true;
            dashTimer = 0f;
            targetFOV = dashFOV;
            lastDashPosition = transform.position;
            _hitThisDash.Clear();
        }

        private void HandleDash()
        {
            dashTimer += Time.deltaTime;

            if (dashTimer >= dashDuration)
            {
                EndDash();
            }
        }

        // Vérifie si le dash doit être arrêté par une collision avec un obstacle à mauvais angle
        private bool CheckObstacleCollision()
        {
            // Raycast dans la direction du dash pour détecter les obstacles
            RaycastHit hit;
            float checkDistance = obstacleCheckDistance;

            // SphereCast pour détecter les obstacles devant le joueur avec un rayon similaire au dashHitRadius
            if (Physics.SphereCast(
                transform.position,
                dashHitRadius * 0.8f, // Légèrement plus petit pour éviter les faux positifs
                directionalDashDir,
                out hit,
                checkDistance,
                obstacleMask,
                QueryTriggerInteraction.Ignore))
            {
                // Ignorer si c'est un ennemi (ils sont gérés séparément)
                var enemyHealth = hit.collider.GetComponentInParent<EnemyHealth>() ?? hit.collider.GetComponent<EnemyHealth>();
                if (enemyHealth != null)
                {
                    return false; // Ne pas arrêter le dash pour les ennemis
                }

                // Calculer l'angle entre la direction du dash et la normale de la surface
                float angle = Vector3.Angle(directionalDashDir, -hit.normal);

                // Debug visuel
                Debug.DrawRay(hit.point, hit.normal * 2f, Color.red, 0.1f);
                Debug.DrawRay(hit.point, directionalDashDir * 2f, Color.yellow, 0.1f);

                // Si l'angle est trop abrupt (surface trop perpendiculaire à la direction du dash)
                if (angle > maxCollisionAngle)
                {
                    Debug.Log($"[DashSystem] Dash arrêté par collision ! Angle: {angle:F1}° (max: {maxCollisionAngle}°)");
                    return true; // Arrêter le dash
                }
            }

            return false; // Continuer le dash
        }


        // Désactive toutes les collisions d'un ennemi pour permettre au dash de passer à travers.
        private void DisableEnemyCollisions(GameObject enemy)
        {

            Collider[] colliders = enemy.GetComponentsInChildren<Collider>();
            foreach (Collider col in colliders)
            {
                col.enabled = false;
            }

            // Désactiver également le rigidbody pour éviter les interactions physiques
            Rigidbody enemyRb = enemy.GetComponent<Rigidbody>();
            if (enemyRb != null)
            {
                enemyRb.isKinematic = true;
                enemyRb.detectCollisions = false;
            }

            Rigidbody[] childRbs = enemy.GetComponentsInChildren<Rigidbody>();
            foreach (Rigidbody childRb in childRbs)
            {
                childRb.isKinematic = true;
                childRb.detectCollisions = false;
            }
        }

        private System.Collections.IEnumerator CleanupEnemyTracking(GameObject enemy)
        {
            yield return new WaitForSeconds(2f);
            if (enemy == null)
            {
                // L'ennemi a bien été détruit, on peut le retirer du tracking
                enemiesKilledByDash.Remove(enemy);
            }
        }

        // Vérifie si un ennemi a été tué par le dash
        public static bool WasKilledByDash(GameObject enemy)
        {
            return enemiesKilledByDash.Contains(enemy);
        }

        private void EndDash()
        {
            // Réactiver le mouvement normal
            if (fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }

            // Appliquer le momentum de sortie si activé
            if (conserveMomentum && fpsMovement != null)
            {
                // Calculer le momentum basé sur la vitesse du dash
                Vector3 dashMomentum = directionalDashDir * dashSpeed * momentumRetention;
                fpsMovement.ApplyExternalMomentum(dashMomentum);

                Debug.Log($"[DashSystem] Momentum conservé: {dashMomentum.magnitude:F1} m/s dans la direction {directionalDashDir}");
            }

            isDashing = false;
            dashTimer = 0f;
            cooldownTimer = 0f;
            targetFOV = defaultFOV;
        }

        private void UpdateFOV()
        {
            if (playerCamera != null)
            {
                playerCamera.fieldOfView = Mathf.Lerp(
                    playerCamera.fieldOfView,
                    targetFOV,
                    Time.deltaTime * fovTransitionSpeed
                );
            }
        }

        public bool CanDash => currentDashCharge >= 1f && !isDashing && (autoRegenerate ? cooldownTimer >= dashCooldown : true);

        public float DashCooldownProgress => Mathf.Clamp01(cooldownTimer / dashCooldown);

        public float CurrentDashCharge => currentDashCharge;

        // Appelé quand un ennemi spécial (DashEnergyEnemy) est tué
        public void OnDashEnemyKilled(float energyAmount)
        {
            float oldCharge = currentDashCharge;

            // Calculer l'énergie par ennemi (1 / nombre d'ennemis requis)
            float energyPerEnemy = 1f / Mathf.Max(1, enemiesRequiredForFullCharge);

            // Ajouter l'énergie (multipliée par le montant configuré sur l'ennemi)
            currentDashCharge = Mathf.Clamp01(currentDashCharge + (energyPerEnemy * energyAmount));

            Debug.Log($"[DashSystem] Dash rechargé! {oldCharge:P0} → {currentDashCharge:P0} (+{energyPerEnemy * energyAmount:P0})");
        }
    }
}

using FPS;
using UnityEngine;

[RequireComponent(typeof(PlayerHealth))]
public class Death : MonoBehaviour
{
    [SerializeField] private Transform spawnRoot;

    private PlayerHealth playerHealth;
    private CharacterController characterController;
    private Vector3 spawnPosition;
    private Quaternion spawnRotation;

    // Start is called once before the first execution of Update after the MonoBehaviour is created
    void Awake()
    {
        playerHealth = GetComponent<PlayerHealth>();
        characterController = GetComponent<CharacterController>();
        spawnRoot = spawnRoot != null ? spawnRoot : transform;
    }

    private void OnEnable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.AddListener(HandleDeath);
        }
    }

    private void Start()
    {
        CacheSpawnPoint();
    }

    private void OnDisable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.RemoveListener(HandleDeath);
        }
    }

    private void CacheSpawnPoint()
    {
        spawnPosition = spawnRoot.position;
        spawnRotation = spawnRoot.rotation;
    }

    public void SetSpawnPoint(Transform newSpawn)
    {
        if (newSpawn == null) return;
        spawnRoot = newSpawn;
        CacheSpawnPoint();
    }

    private void HandleDeath()
    {
        RespawnPlayer();
        playerHealth.ResetHealth();
    }

    private void RespawnPlayer()
    {
        bool controllerInitiallyEnabled = characterController != null && characterController.enabled;
        if (characterController != null)
        {
            characterController.enabled = false;
        }

        transform.SetPositionAndRotation(spawnPosition, spawnRotation);

        if (controllerInitiallyEnabled)
        {
            characterController.enabled = true;
        }
    }
}

using FPS;
using UnityEngine;

[RequireComponent(typeof(PlayerHealth))]
public class Death : MonoBehaviour
{
    [SerializeField] private Transform spawnRoot;

    private PlayerHealth playerHealth;
    private Rigidbody rb;
    private Vector3 spawnPosition;
    private Quaternion spawnRotation;

    // Start is called once before the first execution of Update after the MonoBehaviour is created
    void Awake()
    {
        playerHealth = GetComponent<PlayerHealth>();
        rb = GetComponent<Rigidbody>();
        spawnRoot = spawnRoot != null ? spawnRoot : transform;
    }

    private void OnEnable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.AddListener(HandleDeath);
        }
    }

    private void Start()
    {
        CacheSpawnPoint();
    }

    private void OnDisable()
    {
        if (playerHealth != null)
        {
            playerHealth.OnDeath.RemoveListener(HandleDeath);
        }
    }

    private void CacheSpawnPoint()
    {
        spawnPosition = spawnRoot.position;
        spawnRotation = spawnRoot.rotation;
    }

    public void SetSpawnPoint(Transform newSpawn)
    {
        if (newSpawn == null) return;
        spawnRoot = newSpawn;
        CacheSpawnPoint();
    }

    private void HandleDeath()
    {
        RespawnPlayer();
        playerHealth.ResetHealth();
    }

    private void RespawnPlayer()
    {
        if (rb != null)
        {
            // Reset velocity before teleporting
            rb.linearVelocity = Vector3.zero;
            rb.angularVelocity = Vector3.zero;

            // Teleport using Rigidbody
            rb.position = spawnPosition;
            rb.rotation = spawnRotation;
        }
        else
        {
            transform.SetPositionAndRotation(spawnPosition, spawnRotation);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

namespace FPS
{
    // Gère la santé de l'ennemi avec zones de dégâts et tracking des hits.
    public class EnemyHealth : MonoBehaviour
    {
        [Header("Health Settings")]
        [SerializeField] private float maxHealth = 100f;
        [SerializeField] private float currentHealth;

        [Header("Spawn Invulnerability")]
        [Tooltip("Durée d'invulnérabilité après l'apparition (secondes)")]
        [SerializeField] private float spawnInvulnerabilityDuration = 0f;
        [Tooltip("Si vrai, invulnérable à tous les types de dégâts pendant l'invulnérabilité; sinon seulement aux balles")]
        [SerializeField] private bool spawnInvulnerableAllDamage = false;
        private float spawnInvulnerableUntil;

        [Header("Hit Tracking")]
        [SerializeField] private Dictionary<string, int> zoneHitCount = new Dictionary<string, int>();

        [Header("Events")]
        public UnityEvent OnDeath;
        public UnityEvent<float, string> OnDamageTaken;

        private bool isDead;
        private WaveManager waveManager;

        // Centralisation: suivi de l'origine des dégâts/kill
        private DamageType lastHitType = DamageType.Other;
        private DamageType lastKillType = DamageType.Other;
        private Transform lastAttacker;

        private void Awake()
        {
            currentHealth = maxHealth;
            spawnInvulnerableUntil = Time.time + Mathf.Max(0f, spawnInvulnerabilityDuration);
            waveManager = FindFirstObjectByType<WaveManager>();
        }

        private void EnsureWaveManager()
        {
            if (waveManager == null)
            {
                waveManager = FindFirstObjectByType<WaveManager>();
            }
        }

        private bool IsSpawnInvulnerableFor(DamageType type)
        {
            if (Time.time < spawnInvulnerableUntil)
            {
                if (spawnInvulnerableAllDamage) return true;
                return type == DamageType.Bullet;
            }
            return false;
        }

        // Nouveau pipeline: tente d'appliquer un dégât détaillé. Retourne true si appliqué.
        public bool TryApplyDamage(DamageInfo info)
        {
            if (isDead) return false;
            // Intercepteurs (ex: MagicEnemy) — peuvent bloquer et déclencher des effets (renvoi)
            bool allow = true;
            var interceptors = GetComponents<IDamageInterceptor>();
            if (interceptors != null && interceptors.Length > 0)
            {
                for (int i = 0; i < interceptors.Length; i++)
                {
                    try { allow = interceptors[i].OnBeforeDamage(ref info) && allow; } catch {}
                }
            }
            if (!allow) return false;

            // Invulnérabilité de spawn propre (bloque sans "retirer puis remettre")
            if (IsSpawnInvulnerableFor(info.type))
            {
                return false;
            }

            // Appliquer
            float damage = Mathf.Max(0f, info.amount);
            string zoneName = string.IsNullOrWhiteSpace(info.zoneName) ? "Body" : info.zoneName;
            currentHealth -= damage;

            // Centralisation: enregistrer la source du dernier coup
            lastHitType = info.type;
            lastAttacker = info.attacker;

            // Enregistrer le hit
            string key = NormalizeZoneKey(zoneName);
            if (!zoneHitCount.ContainsKey(key)) zoneHitCount[key] = 0;
            zoneHitCount[key]++;

            // Événement de dégâts pris (après application)
            OnDamageTaken?.Invoke(damage, zoneName);

            // Déclencher l'effet électrique si c'est un ennemi électrique mais seulement si les dégâts ne viennent pas déjà d'une décharge électrique
            if (info.type != DamageType.Electric)
            {
                var electricEnemy = GetComponent<Ennemies.Effect.ElectricEnnemis>();
                if (electricEnemy != null)
                {
                    electricEnemy.TriggerElectricDischarge();
                }
            }

            if (currentHealth <= 0)
            {
                // Centralisation: consigner le type de kill avant la mort
                lastKillType = info.type;
                Die();
            }
            return true;
        }

        // Compat: Inflige des dégâts à l'ennemi et enregistre la zone touchée.
        public void TakeDamage(float damage, string zoneName)
        {
            // Considéré comme dégât de balle par défaut
            var info = new DamageInfo(damage, zoneName, DamageType.Bullet);
            TryApplyDamage(info);
        }

        // Overload simple (zone par défaut)
        public void TakeDamage(float damage)
        {
            TakeDamage(damage, "Body");
        }

        // Nouveau: API directe avec DamageInfo
        public void TakeDamage(in DamageInfo info)
        {
            TryApplyDamage(info);
        }

        private void Die()
        {
            if (isDead) return;

            isDead = true;
            OnDeath?.Invoke();

            // Notifier le wave manager qu'un ennemi est mort
            EnsureWaveManager();
            if (waveManager != null)
            {
                waveManager.OnEnemyDeath(this);
            }

            Destroy(gameObject);
        }

        private static string NormalizeZoneKey(string zone)
        {
            return string.IsNullOrWhiteSpace(zone) ? string.Empty : zone.Trim().ToLowerInvariant();
        }

        public float CurrentHealth => currentHealth;
        public float MaxHealth => maxHealth;
        public bool IsDead => isDead;
        public Dictionary<string, int> ZoneHitCount => zoneHitCount;

        // Centralisation: exposer la cause de mort et la source
        public DamageType LastHitType => lastHitType;
        public DamageType LastKillType => lastKillType;
        public Transform LastAttacker => lastAttacker;

        // Tue immédiatement cet ennemi sans enregistrer de hit
        public void KillImmediate()
        {
            if (isDead) return;
            currentHealth = 0f;
            lastKillType = DamageType.Other;
            Die();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

namespace FPS
{
    // Gère la santé de l'ennemi avec zones de dégâts et tracking des hits.
    public class EnemyHealth : MonoBehaviour
    {
        [Header("Health Settings")]
        [SerializeField] private float maxHealth = 100f;
        [SerializeField] private float currentHealth;

        [Header("Spawn Invulnerability")]
        [Tooltip("Durée d'invulnérabilité après l'apparition (secondes)")]
        [SerializeField] private float spawnInvulnerabilityDuration = 0f;
        [Tooltip("Si vrai, invulnérable à tous les types de dégâts pendant l'invulnérabilité; sinon seulement aux balles")]
        [SerializeField] private bool spawnInvulnerableAllDamage = false;
        private float spawnInvulnerableUntil;

        [Header("Hit Tracking")]
        [SerializeField] private Dictionary<string, int> zoneHitCount = new Dictionary<string, int>();

        [Header("Events")]
        public UnityEvent OnDeath;
        public UnityEvent<float, string> OnDamageTaken;

        private bool isDead;
        private WaveManager waveManager;

        // Centralisation: suivi de l'origine des dégâts/kill
        private DamageType lastHitType = DamageType.Other;
        private DamageType lastKillType = DamageType.Other;
        private Transform lastAttacker;

        private void Awake()
        {
            currentHealth = maxHealth;
            spawnInvulnerableUntil = Time.time + Mathf.Max(0f, spawnInvulnerabilityDuration);
            waveManager = FindFirstObjectByType<WaveManager>();
        }

        private void EnsureWaveManager()
        {
            if (waveManager == null)
            {
                waveManager = FindFirstObjectByType<WaveManager>();
            }
        }

        private bool IsSpawnInvulnerableFor(DamageType type)
        {
            if (Time.time < spawnInvulnerableUntil)
            {
                if (spawnInvulnerableAllDamage) return true;
                return type == DamageType.Bullet;
            }
            return false;
        }

        // Nouveau pipeline: tente d'appliquer un dégât détaillé. Retourne true si appliqué.
        public bool TryApplyDamage(DamageInfo info)
        {
            if (isDead) return false;
            // Intercepteurs (ex: MagicEnemy) — peuvent bloquer et déclencher des effets (renvoi)
            bool allow = true;
            var interceptors = GetComponents<IDamageInterceptor>();
            if (interceptors != null && interceptors.Length > 0)
            {
                for (int i = 0; i < interceptors.Length; i++)
                {
                    try { allow = interceptors[i].OnBeforeDamage(ref info) && allow; } catch {}
                }
            }
            if (!allow) return false;

            // Invulnérabilité de spawn propre (bloque sans "retirer puis remettre")
            if (IsSpawnInvulnerableFor(info.type))
            {
                return false;
            }

            // Appliquer
            float damage = Mathf.Max(0f, info.amount);
            string zoneName = string.IsNullOrWhiteSpace(info.zoneName) ? "Body" : info.zoneName;
            currentHealth -= damage;

            // Centralisation: enregistrer la source du dernier coup
            lastHitType = info.type;
            lastAttacker = info.attacker;

            // Enregistrer le hit
            string key = NormalizeZoneKey(zoneName);
            if (!zoneHitCount.ContainsKey(key)) zoneHitCount[key] = 0;
            zoneHitCount[key]++;

            // Événement de dégâts pris (après application)
            OnDamageTaken?.Invoke(damage, zoneName);

            // Déclencher l'effet électrique si c'est un ennemi électrique mais seulement si les dégâts ne viennent pas déjà d'une décharge électrique
            if (info.type != DamageType.Electric)
            {
                var electricEnemy = GetComponent<Ennemies.Effect.ElectricEnnemis>();
                if (electricEnemy != null)
                {
                    electricEnemy.TriggerElectricDischarge();
                }
            }

            // Appliquer le knockback si c'est un dash et que l'ennemi ne résiste pas
            if (info.type == DamageType.Dash)
            {
                TryApplyDashKnockback(info);
            }

            if (currentHealth <= 0)
            {
                // Centralisation: consigner le type de kill avant la mort
                lastKillType = info.type;
                Die();
            }
            return true;
        }

        // Compat: Inflige des dégâts à l'ennemi et enregistre la zone touchée.
        public void TakeDamage(float damage, string zoneName)
        {
            // Considéré comme dégât de balle par défaut
            var info = new DamageInfo(damage, zoneName, DamageType.Bullet);
            TryApplyDamage(info);
        }

        // Overload simple (zone par défaut)
        public void TakeDamage(float damage)
        {
            TakeDamage(damage, "Body");
        }

        // Nouveau: API directe avec DamageInfo
        public void TakeDamage(in DamageInfo info)
        {
            TryApplyDamage(info);
        }

        private void Die()
        {
            if (isDead) return;

            isDead = true;
            OnDeath?.Invoke();

            // Notifier le wave manager qu'un ennemi est mort
            EnsureWaveManager();
            if (waveManager != null)
            {
                waveManager.OnEnemyDeath(this);
            }

            Destroy(gameObject);
        }

        private static string NormalizeZoneKey(string zone)
        {
            return string.IsNullOrWhiteSpace(zone) ? string.Empty : zone.Trim().ToLowerInvariant();
        }

        public float CurrentHealth => currentHealth;
        public float MaxHealth => maxHealth;
        public bool IsDead => isDead;
        public Dictionary<string, int> ZoneHitCount => zoneHitCount;

        // Centralisation: exposer la cause de mort et la source
        public DamageType LastHitType => lastHitType;
        public DamageType LastKillType => lastKillType;
        public Transform LastAttacker => lastAttacker;

        // Tue immédiatement cet ennemi sans enregistrer de hit
        public void KillImmediate()
        {
            if (isDead) return;
            currentHealth = 0f;
            lastKillType = DamageType.Other;
            Die();
        }

        /// <summary>
        /// Tente d'appliquer le knockback lors d'un dash si l'ennemi n'y résiste pas.
        /// </summary>
        private void TryApplyDashKnockback(DamageInfo info)
        {
            // Vérifier si l'ennemi résiste au dash (ex: ElectricEnnemis avec ResistToDash)
            var electricEnemy = GetComponent<Ennemies.Effect.ElectricEnnemis>();
            if (electricEnemy != null && electricEnemy.ResistToDash)
            {
                return;
            }

            // Récupérer ou créer le composant de knockback
            var knockback = GetComponent<EnemyKnockback>();
            if (knockback == null)
            {
                // Auto-ajouter le Rigidbody s'il n'existe pas
                var rb = GetComponent<Rigidbody>();
                if (rb == null)
                {
                    rb = gameObject.AddComponent<Rigidbody>();
                    rb.isKinematic = true;
                    rb.interpolation = RigidbodyInterpolation.Interpolate;
                    rb.constraints = RigidbodyConstraints.FreezeRotation;
                }

                // Auto-ajouter le composant EnemyKnockback
                knockback = gameObject.AddComponent<EnemyKnockback>();
            }

            if (knockback.ResistToKnockback)
            {
                return;
            }

            // Calculer la direction du knockback (depuis l'attaquant vers l'ennemi)
            Vector3 knockbackDirection;
            if (info.attacker != null)
            {
                knockbackDirection = (transform.position - info.attacker.position).normalized;
            }
            else if (info.hitNormal != Vector3.zero)
            {
                // Utiliser l'inverse de la normale de hit comme direction
                knockbackDirection = -info.hitNormal.normalized;
            }
            else
            {
                // Fallback: direction par défaut (vers l'arrière de l'ennemi)
                knockbackDirection = -transform.forward;
            }

            // Récupérer les paramètres de knockback depuis le DashCible du joueur
            float force = 15f;      // Valeur par défaut
            float duration = 0.5f;  // Valeur par défaut
            bool affectsY = false;  // Valeur par défaut

            // Essayer de récupérer les paramètres du DashDefinition via le joueur
            if (info.attacker != null)
            {
                var dashCible = info.attacker.GetComponent<DashCible>();
                if (dashCible != null)
                {
                    var dashDef = GetDashDefinitionFromPlayer(dashCible);
                    if (dashDef != null)
                    {
                        force = dashDef.knockbackForce;
                        duration = dashDef.knockbackDuration;
                        affectsY = dashDef.knockbackAffectsYAxis;
                    }
                }
            }

            // Appliquer le knockback
            knockback.ApplyKnockback(knockbackDirection, force, duration, affectsY);
        }

        /// <summary>
        /// Récupère le DashDefinition depuis le DashCible via réflexion (pour éviter de modifier DashCible).
        /// </summary>
        private DashDefinition GetDashDefinitionFromPlayer(DashCible dashCible)
        {
            // Utiliser la réflexion pour accéder au champ privé dashDefinition
            var field = typeof(DashCible).GetField("dashDefinition", 
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            if (field != null)
            {
                return field.GetValue(dashCible) as DashDefinition;
            }
            return null;
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.AI;

namespace FPS
{
    /// <summary>
    /// Gère le knockback physique des ennemis lors d'un dash.
    /// Utilise un Rigidbody pour la physique et réactive le NavMeshAgent après le knockback.
    /// </summary>
    [RequireComponent(typeof(Rigidbody))]
    public class EnemyKnockback : MonoBehaviour
    {
        [Header("Knockback Settings")]
        [Tooltip("Si true, cet ennemi résiste au knockback (ne sera pas repoussé)")]
        [SerializeField] private bool resistToKnockback = false;

        [Header("Visual Feedback")]
        [Tooltip("Particule d'impact à instancier lors du knockback")]
        [SerializeField] private GameObject impactParticlePrefab;

        [Tooltip("Offset de position pour la particule d'impact")]
        [SerializeField] private Vector3 particleOffset = Vector3.up * 0.5f;

        [Header("Audio Feedback")]
        [Tooltip("Son d'impact à jouer lors du knockback")]
        [SerializeField] private AudioClip impactSound;

        [Tooltip("Volume du son d'impact")]
        [Range(0f, 1f)]
        [SerializeField] private float impactVolume = 0.8f;

        private Rigidbody rb;
        private NavMeshAgent agent;
        private EnemyVisualFeedback visualFeedback;
        private EnemyHealth enemyHealth;
        private bool isKnockbackActive;
        private Coroutine knockbackCoroutine;

        /// <summary>
        /// Indique si cet ennemi résiste au knockback
        /// </summary>
        public bool ResistToKnockback => resistToKnockback;

        /// <summary>
        /// Indique si un knockback est actuellement en cours
        /// </summary>
        public bool IsKnockbackActive => isKnockbackActive;

        private void Awake()
        {
            rb = GetComponent<Rigidbody>();
            agent = GetComponent<NavMeshAgent>();
            visualFeedback = GetComponent<EnemyVisualFeedback>();
            enemyHealth = GetComponent<EnemyHealth>();

            // Configuration initiale du Rigidbody
            if (rb != null)
            {
                rb.isKinematic = true;
                rb.interpolation = RigidbodyInterpolation.Interpolate;
                rb.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
                // Bloquer la rotation pour éviter que l'ennemi tourne pendant le knockback
                rb.constraints = RigidbodyConstraints.FreezeRotation;
            }
        }

        /// <summary>
        /// Applique un knockback à l'ennemi dans la direction spécifiée.
        /// </summary>
        /// <param name="direction">Direction du knockback (normalisée)</param>
        /// <param name="force">Force du knockback</param>
        /// <param name="duration">Durée du knockback avant de réactiver l'IA</param>
        /// <param name="affectsYAxis">Si true, applique aussi la force sur l'axe Y</param>
        public void ApplyKnockback(Vector3 direction, float force, float duration, bool affectsYAxis = false)
        {
            // Vérifier la résistance au knockback
            if (resistToKnockback) return;

            // Vérifier si l'ennemi est mort
            if (enemyHealth != null && enemyHealth.IsDead) return;

            // Vérifier les composants nécessaires
            if (rb == null) return;

            // Si un knockback est déjà en cours, l'interrompre
            if (knockbackCoroutine != null)
            {
                StopCoroutine(knockbackCoroutine);
            }

            knockbackCoroutine = StartCoroutine(KnockbackCoroutine(direction, force, duration, affectsYAxis));
        }

        private IEnumerator KnockbackCoroutine(Vector3 direction, float force, float duration, bool affectsYAxis)
        {
            isKnockbackActive = true;

            // Normaliser la direction
            direction = direction.normalized;

            // Optionnellement ignorer l'axe Y
            if (!affectsYAxis)
            {
                direction.y = 0f;
                direction = direction.normalized;
            }

            // Désactiver le NavMeshAgent
            if (agent != null && agent.enabled)
            {
                agent.isStopped = true;
                agent.enabled = false;
            }

            // Activer la physique du Rigidbody
            rb.isKinematic = false;

            // Appliquer l'impulsion de knockback
            rb.linearVelocity = Vector3.zero; // Reset velocity
            rb.AddForce(direction * force, ForceMode.VelocityChange);

            // Jouer les feedbacks
            PlayImpactFeedback();

            // Attendre la durée du knockback (utiliser unscaledDeltaTime pour ignorer le slow-mo)
            float elapsed = 0f;
            while (elapsed < duration)
            {
                // Vérifier si l'ennemi est mort pendant le knockback
                if (enemyHealth != null && enemyHealth.IsDead)
                {
                    isKnockbackActive = false;
                    yield break;
                }

                elapsed += Time.unscaledDeltaTime;
                yield return null;
            }

            // Arrêter le mouvement
            rb.linearVelocity = Vector3.zero;
            rb.angularVelocity = Vector3.zero;

            // Réactiver le Rigidbody en mode kinématique
            rb.isKinematic = true;

            // Réactiver le NavMeshAgent avec Warp pour éviter les problèmes de position
            if (agent != null)
            {
                // Trouver la position valide la plus proche sur le NavMesh
                if (NavMesh.SamplePosition(rb.position, out NavMeshHit hit, 5f, NavMesh.AllAreas))
                {
                    agent.enabled = true;
                    agent.Warp(hit.position);
                    agent.isStopped = false;
                }
                else
                {
                    // Si pas de position NavMesh trouvée, activer quand même l'agent
                    agent.enabled = true;
                    agent.isStopped = false;
                }
            }

            isKnockbackActive = false;
            knockbackCoroutine = null;
        }

        private void PlayImpactFeedback()
        {
            // Feedback visuel (flash)
            if (visualFeedback != null)
            {
                visualFeedback.ShowHitFeedback();
            }

            // Particule d'impact
            if (impactParticlePrefab != null)
            {
                Vector3 spawnPos = transform.position + particleOffset;
                GameObject particle = Instantiate(impactParticlePrefab, spawnPos, Quaternion.identity);

                // Auto-destruction de la particule
                var ps = particle.GetComponent<ParticleSystem>();
                if (ps != null)
                {
                    Destroy(particle, ps.main.duration + ps.main.startLifetime.constantMax);
                }
                else
                {
                    Destroy(particle, 2f);
                }
            }

            // Son d'impact
            if (impactSound != null)
            {
                AudioSource.PlayClipAtPoint(impactSound, transform.position, impactVolume);
            }
        }

        /// <summary>
        /// Force l'arrêt du knockback en cours (utile si l'ennemi meurt)
        /// </summary>
        public void CancelKnockback()
        {
            if (knockbackCoroutine != null)
            {
                StopCoroutine(knockbackCoroutine);
                knockbackCoroutine = null;
            }

            isKnockbackActive = false;

            // Remettre le Rigidbody en mode kinématique
            if (rb != null)
            {
                rb.linearVelocity = Vector3.zero;
                rb.isKinematic = true;
            }
        }

        private void OnDestroy()
        {
            CancelKnockback();
        }
    }
}

using System.Collections;
using UnityEngine;

namespace FPS
{
    public class DashCible : MonoBehaviour
    {
        [Header("Ciblage")]
        [SerializeField] private Camera aimCamera;

        [Header("Définition du Dash")]
        [SerializeField] private DashDefinition dashDefinition;
        [SerializeField] private BounceDefinition groundBounce;
        [SerializeField] private BounceDefinition airBounce;

        [Header("Input")]
        [SerializeField] private KeyCode activationKey = KeyCode.Q;

        [Header("Références Joueur")]
        [SerializeField] private FPSPlayerController playerController;
        [SerializeField] private Rigidbody rb;
        [SerializeField] private FPSMovement fpsMovement;
        private PlayerHealth playerHealth;

        public bool isDashing;
        private bool chainActive;
        private int remainingChains;
        private float nextAvailableTime;
        private float slowMoEndUnscaled;
        public bool slowMoApplied;
        private float previousTimeScale = 1f;
        private bool pathElectricStunned;
        private float dashStartTime; // Pour détecter les dashs bloqués
        private Coroutine bounceCoroutine; // Coroutine de rebond active
        private bool hitStopActive; // Flag pour le hitstop en cours

        private static readonly Collider[] OverlapBuffer = new Collider[16];

        private DashDefinition Config => dashDefinition;
        private LayerMask EnemyMask => Config?.enemyMask ?? ~0;
        private LayerMask ObstacleMask => Config?.obstacleMask ?? ~0;
        private float MaxAimAngle => Mathf.Max(0f, Config?.maxAimAngle ?? 30f);
        private int ConfigCountDash => Mathf.Max(1, Config?.countDash ?? 3);
        private float ConfigSlowMoTime => Mathf.Max(0.01f, Config?.slowMoTime ?? 0.75f);
        private float ConfigSlowMoScale => Mathf.Clamp(Config?.slowMoScale ?? 0.2f, 0.01f, 1f);
        private float ConfigDistanceDash => Mathf.Max(0.5f, Config?.distanceDash ?? 25f);
        private float ConfigCooldown => Mathf.Max(0f, Config?.cooldown ?? 1.5f);
        private float ConfigDashDamage => Mathf.Max(0f, Config?.dashDamage ?? 9999f);
        private float ConfigDashTravelTime => Mathf.Max(0.01f, Config?.dashTravelTime ?? 0.08f);
        private float ConfigCapsuleRadius => Mathf.Max(0f, Config?.capsuleRadius ?? 0.4f);
        private float ConfigStopOffset => Mathf.Max(0f, Config?.stopOffset ?? 1f);
        private float ConfigHitStopDuration => Mathf.Max(0f, Config?.hitStopUnscaledDuration ?? 0f);
        private bool ConfigHitStopFreezeTime => Config?.hitStopFreezeTime ?? true;
        private BounceDefinition CurrentBounce
        {
            get
            {
                bool grounded = fpsMovement == null || fpsMovement.IsGrounded;
                if (grounded)
                    return groundBounce ?? airBounce;
                return airBounce ?? groundBounce;
            }
        }

        private void Awake()
        {
            if (playerController == null)
                playerController = GetComponent<FPSPlayerController>();
            if (fpsMovement == null)
                fpsMovement = GetComponent<FPSMovement>();
            // Obtenir le Rigidbody directement pour éviter les problèmes d'ordre d'exécution
            if (rb == null)
                rb = GetComponent<Rigidbody>();
            if (aimCamera == null)
                aimCamera = Camera.main;
            playerHealth = GetComponent<PlayerHealth>();
        }

        private void Update()
        {
            // Sécurité: détecter si le dash est bloqué (plus de 2 secondes)
            if (isDashing && Time.unscaledTime - dashStartTime > 2f)
            {
                Debug.LogWarning("[DashCible] Dash bloqué depuis plus de 2s! Réinitialisation forcée.");
                FinalizeDash();
                if (chainActive) EndChain();
            }

            if (slowMoApplied && Time.unscaledTime >= slowMoEndUnscaled)
            {
                ClearSlowMo();
                if (!isDashing && chainActive)
                {
                    EndChain();
                }
            }

            if (Input.GetKeyDown(activationKey))
            {
                TryTriggerOrChain();
            }
        }

        private void TryTriggerOrChain()
        {
            // Vérifier si le mouvement est bloqué (bug potentiel)
            if (fpsMovement != null && fpsMovement.IsMovementDisabled && !isDashing)
            {
                Debug.LogWarning("[DashCible] Mouvement était désactivé alors qu'on ne dashait pas! Réactivation forcée.");
                fpsMovement.EnableMovement();
            }

            if (isDashing)
            {
                Debug.Log("[DashCible] Dash bloqué: déjà en train de dasher");
                return;
            }

            // Si la chaîne est active mais le slow-mo a expiré et le cooldown est terminé,
            // on peut recommencer une nouvelle chaîne
            if (chainActive && !slowMoApplied && Time.time >= nextAvailableTime)
            {
                Debug.Log("[DashCible] Chaîne précédente expirée, reset pour nouvelle chaîne");
                chainActive = false;
            }

            bool isFirstDash = !chainActive;

            if (!chainActive)
            {
                if (Time.time < nextAvailableTime)
                {
                    Debug.Log($"[DashCible] Dash bloqué: cooldown actif ({nextAvailableTime - Time.time:F2}s restant)");
                    return;
                }
                remainingChains = ConfigCountDash;
                chainActive = true;
                Debug.Log($"[DashCible] Nouvelle chaîne démarrée, {remainingChains} dashs disponibles");
            }
            else
            {
                if (!slowMoApplied || remainingChains <= 0)
                {
                    Debug.Log($"[DashCible] Dash bloqué: slowMo={slowMoApplied}, remainingChains={remainingChains}");
                    return;
                }
            }

            var target = AcquireTarget();
            if (target == null)
            {
                Debug.Log("[DashCible] Pas de cible trouvée");
                // Pas de cible trouvée
                if (isFirstDash)
                {
                    // Premier dash sans cible - annuler la chaîne
                    chainActive = false;
                }
                // Sinon, ignorer le clic sans annuler la chaîne (le slow-mo continue)
                return;
            }

            remainingChains = Mathf.Max(0, remainingChains - 1);
            StartCoroutine(DoTargetDash(target));
        }

        private EnemyHealth AcquireTarget()
        {
            if (aimCamera == null) return null;

            Ray ray = aimCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
            if (Physics.Raycast(ray, out RaycastHit hit, ConfigDistanceDash, EnemyMask, QueryTriggerInteraction.Ignore))
            {
                var eh = hit.collider.GetComponentInParent<EnemyHealth>() ?? hit.collider.GetComponent<EnemyHealth>();
                if (eh != null && !eh.IsDead)
                {
                    if (!IsObstructed(aimCamera.transform.position, eh.transform.position))
                        return eh;
                }
            }

            var all = FindObjectsByType<EnemyHealth>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
            EnemyHealth best = null;
            float bestScore = float.MaxValue;
            Vector3 camPos = aimCamera.transform.position;
            Vector3 camFwd = aimCamera.transform.forward;

            foreach (var eh in all)
            {
                if (eh == null || eh.IsDead) continue;
                Vector3 to = eh.transform.position - camPos;
                float dist = to.magnitude;
                if (dist > ConfigDistanceDash) continue;
                Vector3 dir = to / (dist + 1e-5f);
                float angle = Mathf.Acos(Mathf.Clamp(Vector3.Dot(camFwd, dir), -1f, 1f)) * Mathf.Rad2Deg;
                if (angle > MaxAimAngle) continue;
                if (IsObstructed(camPos, eh.transform.position)) continue;
                float score = angle * 2f + dist * 0.2f;
                if (score < bestScore)
                {
                    bestScore = score;
                    best = eh;
                }
            }

            return best;
        }

        private bool IsObstructed(Vector3 from, Vector3 to)
        {
            Vector3 dir = to - from;
            float dist = dir.magnitude;
            if (dist <= 0.01f) return false;
            // Utiliser uniquement ObstacleMask sans le layer des ennemis
            LayerMask obstructionMask = ObstacleMask & ~EnemyMask;
            return Physics.Raycast(from, dir.normalized, dist - 0.1f, obstructionMask, QueryTriggerInteraction.Ignore);
        }

        private IEnumerator DoTargetDash(EnemyHealth target)
        {
            Debug.Log($"[DashCible] DoTargetDash démarré vers {target.name}");
            isDashing = true;
            dashStartTime = Time.unscaledTime;
            pathElectricStunned = false;

            Vector3 start = transform.position;
            Vector3 targetPos = target.transform.position;
            Vector3 dirToTarget = (targetPos - start).normalized;
            float distToTarget = Vector3.Distance(start, targetPos);

            // Calculer la position d'arrêt devant l'ennemi
            float stopDist = Mathf.Clamp(ConfigStopOffset, 0f, Mathf.Max(0f, distToTarget - 0.1f));
            Vector3 end = targetPos - dirToTarget * stopDist;

            if (fpsMovement != null)
            {
                fpsMovement.SetSpeedToMax();
                fpsMovement.DisableMovement();
            }

            float t0 = Time.unscaledTime;
            float dur = Mathf.Max(0.01f, ConfigDashTravelTime);
            Vector3 prev = transform.position;

            while (Time.unscaledTime - t0 < dur)
            {
                // Vérifier si la cible existe encore
                if (target == null)
                {
                    Debug.Log("[DashCible] Cible détruite pendant le dash");
                    break;
                }

                // Recalculer la destination en temps réel (l'ennemi peut bouger)
                targetPos = target.transform.position;

                // Recalculer la direction depuis la position de DEPART (pas la position actuelle)
                // pour maintenir une trajectoire cohérente
                dirToTarget = (targetPos - start).normalized;

                // Recalculer la distance totale et la position d'arrêt
                float currentDistToTarget = Vector3.Distance(start, targetPos);
                stopDist = Mathf.Clamp(ConfigStopOffset, 0f, Mathf.Max(0f, currentDistToTarget - 0.1f));
                end = targetPos - dirToTarget * stopDist;

                float u = (Time.unscaledTime - t0) / dur;
                Vector3 desiredPos = Vector3.Lerp(start, end, u);

                // Vérifier si on a dépassé la position d'arrêt
                float distToEnd = Vector3.Distance(transform.position, end);
                float distFromStartToEnd = Vector3.Distance(start, end);
                float progressToEnd = 1f - (distToEnd / Mathf.Max(0.01f, distFromStartToEnd));

                // Si on est très proche ou on a dépassé, arrêter (mais vérifier les collisions d'abord)
                if (distToEnd < 0.5f || progressToEnd > 0.95f)
                {
                    // Vérifier s'il y a un obstacle entre nous et la position finale
                    Vector3 finalDelta = end - transform.position;
                    Vector3 safeFinalPos = GetSafePosition(transform.position, finalDelta);

                    if (rb != null)
                        rb.MovePosition(safeFinalPos);
                    else
                        transform.position = safeFinalPos;
                    break;
                }

                Vector3 delta = desiredPos - prev;

                // Appliquer le mouvement avec vérification de collision
                if (delta.sqrMagnitude > 0.0001f)
                {
                    Vector3 safePos = GetSafePosition(prev, delta);

                    if (rb != null)
                        rb.MovePosition(safePos);
                    else
                        transform.position = safePos;
                }

                prev = transform.position;

                TryStunElectricOnPath(prev);

                yield return null;
            }

            // Mouvement final vers la destination (seulement si on n'est pas déjà arrivé)
            float finalDistToEnd = Vector3.Distance(transform.position, end);
            if (finalDistToEnd > 0.1f && finalDistToEnd < 3f)
            {
                Vector3 finalDelta = end - transform.position;
                if (finalDelta.sqrMagnitude > 0.0001f)
                {
                    Vector3 safeEndPos = GetSafePosition(transform.position, finalDelta);

                    if (rb != null)
                        rb.MovePosition(safeEndPos);
                    else
                        transform.position = safeEndPos;
                }
            }

            // Vérifier si la cible existe encore avant de continuer
            if (target == null)
            {
                Debug.Log("[DashCible] Cible détruite, fin du dash sans dégâts");
                FinalizeDash();
                yield break;
            }

            // Vérifier si on est assez proche de l'ennemi pour appliquer les dégâts
            float finalDistance = Vector3.Distance(transform.position, target.transform.position);
            // Augmenter la tolérance pour s'assurer que le dash compte comme réussi
            bool reachedTarget = finalDistance <= ConfigStopOffset + 3f;

            Debug.Log($"[DashCible] Distance finale: {finalDistance:F2}, StopOffset: {ConfigStopOffset:F2}, reachedTarget: {reachedTarget}");

            var electric = target.GetComponent<Ennemies.Effect.ElectricEnnemis>();
            if (electric != null)
            {
                var playerStun = GetComponent<PlayerStunAutoFire>();
                if (playerStun == null) playerStun = gameObject.AddComponent<PlayerStunAutoFire>();
                if (electric.OverrideAutoFireInterval)
                    playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                else
                    playerStun.ApplyStun(electric.StunDuration);

                if (electric.ResistToDash)
                {
                    FinalizeDash();
                    ClearSlowMo();
                    EndChain();
                    yield break;
                }
            }

            // Appliquer les dégâts seulement si on a atteint la cible
            if (reachedTarget && target != null)
            {
                var hitCol = target.GetComponentInChildren<Collider>();
                var dmg = new DamageInfo(amount: ConfigDashDamage, zoneName: "Dash", type: DamageType.Dash, hitPoint: target.transform.position, hitNormal: -dirToTarget, attacker: transform, hitCollider: hitCol);
                bool applied = target.TryApplyDamage(dmg);

                if (applied)
                {
                    // Hitstop en temps réel AVANT le slow-mo
                    if (ConfigHitStopDuration > 0f)
                    {
                        yield return StartCoroutine(HitStopRealtime(ConfigHitStopDuration, ConfigHitStopFreezeTime));
                    }

                    ApplyOrRefreshSlowMo();
                    StartBounceImpulse(dirToTarget);
                }
            }

            FinalizeDash();

            if (remainingChains <= 0)
            {
                if (!slowMoApplied)
                {
                    EndChain();
                }
            }
        }

        /// <summary>
        /// Retourne une position sûre en vérifiant les collisions entre la position actuelle et la destination.
        /// Exclut les ennemis pour permettre de dasher à travers eux.
        /// </summary>
        private Vector3 GetSafePosition(Vector3 fromPos, Vector3 delta)
        {
            if (delta.sqrMagnitude < 0.0001f)
                return fromPos;

            float moveLen = delta.magnitude;
            Vector3 moveDir = delta.normalized;

            // Utiliser un SphereCast pour détecter les obstacles (SANS les ennemis)
            float radius = ConfigCapsuleRadius > 0 ? ConfigCapsuleRadius : 0.4f;

            // Exclure les ennemis du masque de collision pour le dash
            LayerMask collisionMask = ObstacleMask & ~EnemyMask;

            if (Physics.SphereCast(fromPos + Vector3.up * 0.5f, radius, moveDir, out RaycastHit hit, moveLen, collisionMask, QueryTriggerInteraction.Ignore))
            {
                // On a touché un obstacle (pas un ennemi), s'arrêter juste avant
                float safeDistance = Mathf.Max(0f, hit.distance - 0.1f);
                return fromPos + moveDir * safeDistance;
            }

            // Pas d'obstacle, on peut aller à la destination
            return fromPos + delta;
        }

        /// <summary>
        /// Calcule un vecteur de déplacement qui glisse le long des obstacles.
        /// </summary>
        private Vector3 SlideMove(Vector3 currentPos, Vector3 desiredDelta)
        {
            Vector3 totalMove = Vector3.zero;
            Vector3 remainingMove = desiredDelta;
            const int maxIterations = 3;

            for (int i = 0; i < maxIterations; i++)
            {
                if (remainingMove.sqrMagnitude < 0.0001f)
                    break;

                float moveLen = remainingMove.magnitude;
                Vector3 moveDir = remainingMove / moveLen;

                Vector3 top = currentPos + totalMove + Vector3.up * 1.5f;
                Vector3 bottom = currentPos + totalMove + Vector3.up * 0.2f;

                if (Physics.CapsuleCast(top, bottom, ConfigCapsuleRadius, moveDir, out RaycastHit hit, moveLen, ObstacleMask, QueryTriggerInteraction.Ignore))
                {
                    // Avancer jusqu'au point de contact (avec une petite marge)
                    float safeDistance = Mathf.Max(0f, hit.distance - 0.05f);
                    Vector3 safeMove = moveDir * safeDistance;
                    totalMove += safeMove;

                    // Calculer le mouvement restant projeté sur le plan de l'obstacle (sliding)
                    float leftoverDist = moveLen - hit.distance;
                    if (leftoverDist > 0.01f)
                    {
                        Vector3 leftoverDir = moveDir * leftoverDist;
                        remainingMove = Vector3.ProjectOnPlane(leftoverDir, hit.normal);
                    }
                    else
                    {
                        break;
                    }
                }
                else
                {
                    // Pas d'obstacle, on peut avancer complètement
                    totalMove += remainingMove;
                    break;
                }
            }

            return totalMove;
        }

        /// <summary>
        /// Finalise le dash en réactivant le mouvement et en mettant à jour les flags
        /// </summary>
        private void FinalizeDash()
        {
            isDashing = false;
            Debug.Log($"[DashCible] Dash finalisé, remainingChains={remainingChains}, slowMoApplied={slowMoApplied}");

            // Réactiver le mouvement normal
            if (fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }
        }

        private void ApplyOrRefreshSlowMo()
        {
            slowMoEndUnscaled = Time.unscaledTime + ConfigSlowMoTime;
            if (!slowMoApplied)
            {
                previousTimeScale = Time.timeScale;
                Time.timeScale = ConfigSlowMoScale;
                Time.fixedDeltaTime = 0.02f * Time.timeScale;
                slowMoApplied = true;
            }
        }

        private void ClearSlowMo()
        {
            if (!slowMoApplied) return;
            Time.timeScale = previousTimeScale;
            Time.fixedDeltaTime = 0.02f * Time.timeScale;
            slowMoApplied = false;

            // S'assurer que le mouvement est réactivé si on n'est plus en train de dasher
            if (!isDashing && fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }
        }

        private void EndChain()
        {
            chainActive = false;
            remainingChains = 0;
            nextAvailableTime = Time.time + ConfigCooldown;

            // S'assurer que le mouvement est réactivé
            if (fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }
        }

        private void OnDisable()
        {
            // Arrêter les coroutines en cours
            if (bounceCoroutine != null)
            {
                StopCoroutine(bounceCoroutine);
                bounceCoroutine = null;
            }

            // Restaurer le temps si hitstop ou slow-mo actif
            if (hitStopActive || slowMoApplied)
            {
                Time.timeScale = 1f;
                Time.fixedDeltaTime = 0.02f;
                hitStopActive = false;
            }
            if (slowMoApplied) ClearSlowMo();
            if (fpsMovement != null) fpsMovement.EnableMovement();
        }

        private void OnDestroy()
        {
            // Arrêter les coroutines en cours
            if (bounceCoroutine != null)
            {
                StopCoroutine(bounceCoroutine);
                bounceCoroutine = null;
            }

            // Restaurer le temps si hitstop ou slow-mo actif
            if (hitStopActive || slowMoApplied)
            {
                Time.timeScale = 1f;
                Time.fixedDeltaTime = 0.02f;
                hitStopActive = false;
            }
            if (slowMoApplied) ClearSlowMo();
            if (fpsMovement != null) fpsMovement.EnableMovement();
        }

        public int CountDash => ConfigCountDash;
        public float SlowMoTime => ConfigSlowMoTime;
        public float DistanceDash => ConfigDistanceDash;
        public float Cooldown => ConfigCooldown;

        public bool IsChainActive => chainActive;
        public int RemainingChains => chainActive ? Mathf.Clamp(remainingChains, 0, ConfigCountDash) : ConfigCountDash;
        public bool IsSlowMoActive => slowMoApplied;

        /// <summary>True si le cooldown global est en cours (après la fin du slow-mo)</summary>
        public bool IsCooldownActive => !chainActive && Time.time < nextAvailableTime;

        /// <summary>Progression du cooldown de 0 (début) à 1 (terminé)</summary>
        public float CooldownProgress => IsCooldownActive 
            ? 1f - ((nextAvailableTime - Time.time) / ConfigCooldown) 
            : 1f;

        private void TryStunElectricOnPath(Vector3 currentPos)
        {
            if (pathElectricStunned) return;
            Vector3 top = currentPos + Vector3.up * 1.5f;
            Vector3 bottom = currentPos + Vector3.up * 0.2f;
            int count = Physics.OverlapCapsuleNonAlloc(top, bottom, ConfigCapsuleRadius, OverlapBuffer, EnemyMask, QueryTriggerInteraction.Ignore);
            for (int i = 0; i < count; i++)
            {
                var col = OverlapBuffer[i];
                if (col == null) continue;
                var electric = col.GetComponentInParent<Ennemies.Effect.ElectricEnnemis>() ?? col.GetComponent<Ennemies.Effect.ElectricEnnemis>();
                if (electric == null) continue;

                var playerStun = GetComponent<PlayerStunAutoFire>() ?? gameObject.AddComponent<PlayerStunAutoFire>();
                if (electric.OverrideAutoFireInterval)
                    playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                else
                    playerStun.ApplyStun(electric.StunDuration);

                pathElectricStunned = true;
                break;
            }
        }

        /// <summary>
        /// Applique un hitstop en temps réel (pause du jeu) avant de continuer.
        /// </summary>
        private IEnumerator HitStopRealtime(float unscaledDuration, bool freezeTime)
        {
            if (unscaledDuration <= 0f)
                yield break;

            hitStopActive = true;

            // Sauvegarder l'état actuel du temps
            float savedTimeScale = Time.timeScale;
            float savedFixedDeltaTime = Time.fixedDeltaTime;

            // Appliquer le freeze
            Time.timeScale = freezeTime ? 0f : 0.01f;
            Time.fixedDeltaTime = 0.02f * Time.timeScale;

            // Attendre en temps réel
            yield return new WaitForSecondsRealtime(unscaledDuration);

            // Restaurer l'état du temps (sauf si slow-mo est déjà appliqué, ce qui sera géré après)
            if (!slowMoApplied)
            {
                Time.timeScale = savedTimeScale;
                Time.fixedDeltaTime = savedFixedDeltaTime;
            }
            else
            {
                // Le slow-mo va être appliqué juste après, on restaure au previousTimeScale
                Time.timeScale = previousTimeScale;
                Time.fixedDeltaTime = 0.02f * previousTimeScale;
            }

            hitStopActive = false;
        }

        /// <summary>
        /// Démarre la coroutine de rebond avec courbe.
        /// </summary>
        private void StartBounceImpulse(Vector3 dashDirection)
        {
            if (bounceCoroutine != null)
            {
                StopCoroutine(bounceCoroutine);
            }
            bounceCoroutine = StartCoroutine(ApplyBounceImpulseOverTime(dashDirection, CurrentBounce));
        }

        /// <summary>
        /// Applique l'impulsion de rebond sur une durée, pilotée par une courbe.
        /// La courbe contrôle la vitesse du rebond à chaque instant (Y=1 = vitesse max, Y=0 = pas de mouvement).
        /// </summary>
        private IEnumerator ApplyBounceImpulseOverTime(Vector3 dashDirection, BounceDefinition config)
        {
            if (config == null || config.force <= 0f)
            {
                bounceCoroutine = null;
                yield break;
            }

            Vector3 dir = ResolveBounceDirection(dashDirection, config);
            if (dir.sqrMagnitude <= 1e-4f)
            {
                bounceCoroutine = null;
                yield break;
            }

            // Si pas de durée ou pas de courbe, appliquer instantanément (comportement legacy)
            if (config.duration <= 0f || config.forceOverTime == null)
            {
                Vector3 instantImpulse = dir.normalized * config.force;
                ApplyMomentum(instantImpulse);
                bounceCoroutine = null;
                yield break;
            }

            // Application sur la durée avec la courbe
            // La courbe définit le multiplicateur de vitesse à chaque instant
            float elapsed = 0f;
            float duration = config.duration;
            Vector3 direction = dir.normalized;

            while (elapsed < duration)
            {
                // Calculer le facteur de la courbe (temps normalisé 0-1)
                float t = elapsed / duration;
                float curveValue = config.forceOverTime.Evaluate(t);

                // La courbe contrôle directement la vitesse à cet instant
                // force = vitesse de base, curveValue = multiplicateur de cette vitesse
                Vector3 velocity = direction * (config.force * curveValue);

                // Appliquer comme momentum (le système de momentum gère le déplacement)
                ApplyMomentum(velocity);

                elapsed += Time.deltaTime;
                yield return null;
            }

            bounceCoroutine = null;
        }

        /// <summary>
        /// Applique un momentum au joueur via fpsMovement ou fallback rb.
        /// </summary>
        private void ApplyMomentum(Vector3 momentum)
        {
            if (fpsMovement != null)
            {
                fpsMovement.ApplyExternalMomentum(momentum);
            }
            else if (rb != null)
            {
                rb.AddForce(momentum, ForceMode.VelocityChange);
            }
            else
            {
                transform.position += momentum * Time.deltaTime;
            }
        }

        private Vector3 ResolveBounceDirection(Vector3 fallbackDashDirection, BounceDefinition config)
        {
            Vector3 dir = config.directionIsLocal ? transform.TransformDirection(config.direction) : config.direction;
            if (dir.sqrMagnitude <= 1e-4f)
                dir = -fallbackDashDirection;
            if (dir.sqrMagnitude <= 1e-4f)
                return Vector3.up;
            return dir.normalized;
        }
    }
}

using System.Collections;
using UnityEngine;

namespace FPS
{
    public class DashCible : MonoBehaviour
    {
        [Header("Ciblage")]
        [SerializeField] private Camera aimCamera;

        [Header("Définition du Dash")]
        [SerializeField] private DashDefinition dashDefinition;
        [SerializeField] private BounceDefinition groundBounce;
        [SerializeField] private BounceDefinition airBounce;

        [Header("Input")]
        [SerializeField] private KeyCode activationKey = KeyCode.Q;

        [Header("Références Joueur")]
        [SerializeField] private FPSPlayerController playerController;
        [SerializeField] private Rigidbody rb;
        [SerializeField] private FPSMovement fpsMovement;
        private PlayerHealth playerHealth;

        public bool isDashing;
        private bool chainActive;
        private int remainingChains;
        private float nextAvailableTime;
        private float slowMoEndUnscaled;
        public bool slowMoApplied;
        private float previousTimeScale = 1f;
        private bool pathElectricStunned;
        private float dashStartTime; // Pour détecter les dashs bloqués
        private Coroutine bounceCoroutine; // Coroutine de rebond active
        private bool hitStopActive; // Flag pour le hitstop en cours

        private static readonly Collider[] OverlapBuffer = new Collider[16];

        private DashDefinition Config => dashDefinition;
        private LayerMask EnemyMask => Config?.enemyMask ?? ~0;
        private LayerMask ObstacleMask => Config?.obstacleMask ?? ~0;
        private float MaxAimAngle => Mathf.Max(0f, Config?.maxAimAngle ?? 30f);
        private int ConfigCountDash => Mathf.Max(1, Config?.countDash ?? 3);
        private float ConfigSlowMoTime => Mathf.Max(0.01f, Config?.slowMoTime ?? 0.75f);
        private float ConfigSlowMoScale => Mathf.Clamp(Config?.slowMoScale ?? 0.2f, 0.01f, 1f);
        private float ConfigDistanceDash => Mathf.Max(0.5f, Config?.distanceDash ?? 25f);
        private float ConfigCooldown => Mathf.Max(0f, Config?.cooldown ?? 1.5f);
        private float ConfigDashDamage => Mathf.Max(0f, Config?.dashDamage ?? 9999f);
        private float ConfigDashTravelTime => Mathf.Max(0.01f, Config?.dashTravelTime ?? 0.08f);
        private float ConfigCapsuleRadius => Mathf.Max(0f, Config?.capsuleRadius ?? 0.4f);
        private float ConfigStopOffset => Mathf.Max(0f, Config?.stopOffset ?? 1f);
        private float ConfigHitStopDuration => Mathf.Max(0f, Config?.hitStopUnscaledDuration ?? 0f);
        private bool ConfigHitStopFreezeTime => Config?.hitStopFreezeTime ?? true;
        private BounceDefinition CurrentBounce
        {
            get
            {
                bool grounded = fpsMovement == null || fpsMovement.IsGrounded;
                if (grounded)
                    return groundBounce ?? airBounce;
                return airBounce ?? groundBounce;
            }
        }

        private void Awake()
        {
            if (playerController == null)
                playerController = GetComponent<FPSPlayerController>();
            if (fpsMovement == null)
                fpsMovement = GetComponent<FPSMovement>();
            // Obtenir le Rigidbody directement pour éviter les problèmes d'ordre d'exécution
            if (rb == null)
                rb = GetComponent<Rigidbody>();
            if (aimCamera == null)
                aimCamera = Camera.main;
            playerHealth = GetComponent<PlayerHealth>();
        }

        private void Update()
        {
            // Sécurité: détecter si le dash est bloqué (plus de 2 secondes)
            if (isDashing && Time.unscaledTime - dashStartTime > 2f)
            {
                Debug.LogWarning("[DashCible] Dash bloqué depuis plus de 2s! Réinitialisation forcée.");
                FinalizeDash();
                if (chainActive) EndChain();
            }

            // Sécurité: si le slow-mo est actif mais le temps a expiré, le désactiver
            if (slowMoApplied && Time.unscaledTime >= slowMoEndUnscaled)
            {
                ClearSlowMo();
                if (!isDashing && chainActive)
                {
                    EndChain();
                }
            }

            // Sécurité supplémentaire: si Time.timeScale est anormalement bas sans slow-mo actif, restaurer
            if (!slowMoApplied && !hitStopActive && !isDashing && Time.timeScale < 0.5f)
            {
                Debug.LogWarning($"[DashCible] TimeScale anormal ({Time.timeScale}) sans slow-mo actif! Restauration à 1.");
                Time.timeScale = 1f;
                Time.fixedDeltaTime = 0.02f;
            }

            if (Input.GetKeyDown(activationKey))
            {
                TryTriggerOrChain();
            }
        }

        private void TryTriggerOrChain()
        {
            // Vérifier si le mouvement est bloqué (bug potentiel)
            if (fpsMovement != null && fpsMovement.IsMovementDisabled && !isDashing)
            {
                Debug.LogWarning("[DashCible] Mouvement était désactivé alors qu'on ne dashait pas! Réactivation forcée.");
                fpsMovement.EnableMovement();
            }

            if (isDashing)
            {
                Debug.Log("[DashCible] Dash bloqué: déjà en train de dasher");
                return;
            }

            // Si la chaîne est active mais le slow-mo a expiré et le cooldown est terminé,
            // on peut recommencer une nouvelle chaîne
            if (chainActive && !slowMoApplied && Time.time >= nextAvailableTime)
            {
                Debug.Log("[DashCible] Chaîne précédente expirée, reset pour nouvelle chaîne");
                chainActive = false;
            }

            bool isFirstDash = !chainActive;

            if (!chainActive)
            {
                if (Time.time < nextAvailableTime)
                {
                    Debug.Log($"[DashCible] Dash bloqué: cooldown actif ({nextAvailableTime - Time.time:F2}s restant)");
                    return;
                }
                remainingChains = ConfigCountDash;
                chainActive = true;
                Debug.Log($"[DashCible] Nouvelle chaîne démarrée, {remainingChains} dashs disponibles");
            }
            else
            {
                if (!slowMoApplied || remainingChains <= 0)
                {
                    Debug.Log($"[DashCible] Dash bloqué: slowMo={slowMoApplied}, remainingChains={remainingChains}");
                    return;
                }
            }

            var target = AcquireTarget();
            if (target == null)
            {
                Debug.Log("[DashCible] Pas de cible trouvée");
                // Pas de cible trouvée
                if (isFirstDash)
                {
                    // Premier dash sans cible - annuler la chaîne
                    chainActive = false;
                }
                // Sinon, ignorer le clic sans annuler la chaîne (le slow-mo continue)
                return;
            }

            remainingChains = Mathf.Max(0, remainingChains - 1);
            StartCoroutine(DoTargetDash(target));
        }

        private EnemyHealth AcquireTarget()
        {
            if (aimCamera == null) return null;

            Ray ray = aimCamera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
            if (Physics.Raycast(ray, out RaycastHit hit, ConfigDistanceDash, EnemyMask, QueryTriggerInteraction.Ignore))
            {
                var eh = hit.collider.GetComponentInParent<EnemyHealth>() ?? hit.collider.GetComponent<EnemyHealth>();
                if (eh != null && !eh.IsDead)
                {
                    if (!IsObstructed(aimCamera.transform.position, eh.transform.position))
                        return eh;
                }
            }

            var all = FindObjectsByType<EnemyHealth>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
            EnemyHealth best = null;
            float bestScore = float.MaxValue;
            Vector3 camPos = aimCamera.transform.position;
            Vector3 camFwd = aimCamera.transform.forward;

            foreach (var eh in all)
            {
                if (eh == null || eh.IsDead) continue;
                Vector3 to = eh.transform.position - camPos;
                float dist = to.magnitude;
                if (dist > ConfigDistanceDash) continue;
                Vector3 dir = to / (dist + 1e-5f);
                float angle = Mathf.Acos(Mathf.Clamp(Vector3.Dot(camFwd, dir), -1f, 1f)) * Mathf.Rad2Deg;
                if (angle > MaxAimAngle) continue;
                if (IsObstructed(camPos, eh.transform.position)) continue;
                float score = angle * 2f + dist * 0.2f;
                if (score < bestScore)
                {
                    bestScore = score;
                    best = eh;
                }
            }

            return best;
        }

        private bool IsObstructed(Vector3 from, Vector3 to)
        {
            Vector3 dir = to - from;
            float dist = dir.magnitude;
            if (dist <= 0.01f) return false;
            // Utiliser uniquement ObstacleMask sans le layer des ennemis
            LayerMask obstructionMask = ObstacleMask & ~EnemyMask;
            return Physics.Raycast(from, dir.normalized, dist - 0.1f, obstructionMask, QueryTriggerInteraction.Ignore);
        }

        private IEnumerator DoTargetDash(EnemyHealth target)
        {
            Debug.Log($"[DashCible] DoTargetDash démarré vers {target.name}");
            isDashing = true;
            dashStartTime = Time.unscaledTime;
            pathElectricStunned = false;

            Vector3 start = transform.position;
            Vector3 targetPos = target.transform.position;
            Vector3 dirToTarget = (targetPos - start).normalized;
            float distToTarget = Vector3.Distance(start, targetPos);

            // Calculer la position d'arrêt devant l'ennemi
            float stopDist = Mathf.Clamp(ConfigStopOffset, 0f, Mathf.Max(0f, distToTarget - 0.1f));
            Vector3 end = targetPos - dirToTarget * stopDist;

            if (fpsMovement != null)
            {
                fpsMovement.SetSpeedToMax();
                fpsMovement.DisableMovement();
            }

            float t0 = Time.unscaledTime;
            float dur = Mathf.Max(0.01f, ConfigDashTravelTime);
            Vector3 prev = transform.position;

            while (Time.unscaledTime - t0 < dur)
            {
                // Vérifier si la cible existe encore
                if (target == null)
                {
                    Debug.Log("[DashCible] Cible détruite pendant le dash");
                    break;
                }

                // Recalculer la destination en temps réel (l'ennemi peut bouger)
                targetPos = target.transform.position;

                // Recalculer la direction depuis la position de DEPART (pas la position actuelle)
                // pour maintenir une trajectoire cohérente
                dirToTarget = (targetPos - start).normalized;

                // Recalculer la distance totale et la position d'arrêt
                float currentDistToTarget = Vector3.Distance(start, targetPos);
                stopDist = Mathf.Clamp(ConfigStopOffset, 0f, Mathf.Max(0f, currentDistToTarget - 0.1f));
                end = targetPos - dirToTarget * stopDist;

                float u = (Time.unscaledTime - t0) / dur;
                Vector3 desiredPos = Vector3.Lerp(start, end, u);

                // Vérifier si on a dépassé la position d'arrêt
                float distToEnd = Vector3.Distance(transform.position, end);
                float distFromStartToEnd = Vector3.Distance(start, end);
                float progressToEnd = 1f - (distToEnd / Mathf.Max(0.01f, distFromStartToEnd));

                // Si on est très proche ou on a dépassé, arrêter (mais vérifier les collisions d'abord)
                if (distToEnd < 0.5f || progressToEnd > 0.95f)
                {
                    // Vérifier s'il y a un obstacle entre nous et la position finale
                    Vector3 finalDelta = end - transform.position;
                    Vector3 safeFinalPos = GetSafePosition(transform.position, finalDelta);

                    if (rb != null)
                        rb.MovePosition(safeFinalPos);
                    else
                        transform.position = safeFinalPos;
                    break;
                }

                Vector3 delta = desiredPos - prev;

                // Appliquer le mouvement avec vérification de collision
                if (delta.sqrMagnitude > 0.0001f)
                {
                    Vector3 safePos = GetSafePosition(prev, delta);

                    if (rb != null)
                        rb.MovePosition(safePos);
                    else
                        transform.position = safePos;
                }

                prev = transform.position;

                TryStunElectricOnPath(prev);

                yield return null;
            }

            // Mouvement final vers la destination (seulement si on n'est pas déjà arrivé)
            float finalDistToEnd = Vector3.Distance(transform.position, end);
            if (finalDistToEnd > 0.1f && finalDistToEnd < 3f)
            {
                Vector3 finalDelta = end - transform.position;
                if (finalDelta.sqrMagnitude > 0.0001f)
                {
                    Vector3 safeEndPos = GetSafePosition(transform.position, finalDelta);

                    if (rb != null)
                        rb.MovePosition(safeEndPos);
                    else
                        transform.position = safeEndPos;
                }
            }

            // Vérifier si la cible existe encore avant de continuer
            if (target == null)
            {
                Debug.Log("[DashCible] Cible détruite, fin du dash sans dégâts");
                FinalizeDash();
                yield break;
            }

            // Vérifier si on est assez proche de l'ennemi pour appliquer les dégâts
            float finalDistance = Vector3.Distance(transform.position, target.transform.position);
            // Augmenter la tolérance pour s'assurer que le dash compte comme réussi
            bool reachedTarget = finalDistance <= ConfigStopOffset + 3f;

            Debug.Log($"[DashCible] Distance finale: {finalDistance:F2}, StopOffset: {ConfigStopOffset:F2}, reachedTarget: {reachedTarget}");

            var electric = target.GetComponent<Ennemies.Effect.ElectricEnnemis>();
            if (electric != null)
            {
                var playerStun = GetComponent<PlayerStunAutoFire>();
                if (playerStun == null) playerStun = gameObject.AddComponent<PlayerStunAutoFire>();
                if (electric.OverrideAutoFireInterval)
                    playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                else
                    playerStun.ApplyStun(electric.StunDuration);

                if (electric.ResistToDash)
                {
                    FinalizeDash();
                    ClearSlowMo();
                    EndChain();
                    yield break;
                }
            }

            // Appliquer les dégâts seulement si on a atteint la cible
            if (reachedTarget && target != null)
            {
                var hitCol = target.GetComponentInChildren<Collider>();
                var dmg = new DamageInfo(amount: ConfigDashDamage, zoneName: "Dash", type: DamageType.Dash, hitPoint: target.transform.position, hitNormal: -dirToTarget, attacker: transform, hitCollider: hitCol);
                bool applied = target.TryApplyDamage(dmg);

                if (applied)
                {
                    // Hitstop en temps réel AVANT le slow-mo
                    if (ConfigHitStopDuration > 0f)
                    {
                        yield return StartCoroutine(HitStopRealtime(ConfigHitStopDuration, ConfigHitStopFreezeTime));
                    }

                    ApplyOrRefreshSlowMo();
                    StartBounceImpulse(dirToTarget);
                }
            }

            FinalizeDash();

            if (remainingChains <= 0)
            {
                if (!slowMoApplied)
                {
                    EndChain();
                }
            }
        }

        /// <summary>
        /// Retourne une position sûre en vérifiant les collisions entre la position actuelle et la destination.
        /// Exclut les ennemis pour permettre de dasher à travers eux.
        /// </summary>
        private Vector3 GetSafePosition(Vector3 fromPos, Vector3 delta)
        {
            if (delta.sqrMagnitude < 0.0001f)
                return fromPos;

            float moveLen = delta.magnitude;
            Vector3 moveDir = delta.normalized;

            // Utiliser un SphereCast pour détecter les obstacles (SANS les ennemis)
            float radius = ConfigCapsuleRadius > 0 ? ConfigCapsuleRadius : 0.4f;

            // Exclure les ennemis du masque de collision pour le dash
            LayerMask collisionMask = ObstacleMask & ~EnemyMask;

            if (Physics.SphereCast(fromPos + Vector3.up * 0.5f, radius, moveDir, out RaycastHit hit, moveLen, collisionMask, QueryTriggerInteraction.Ignore))
            {
                // On a touché un obstacle (pas un ennemi), s'arrêter juste avant
                float safeDistance = Mathf.Max(0f, hit.distance - 0.1f);
                return fromPos + moveDir * safeDistance;
            }

            // Pas d'obstacle, on peut aller à la destination
            return fromPos + delta;
        }

        /// <summary>
        /// Calcule un vecteur de déplacement qui glisse le long des obstacles.
        /// </summary>
        private Vector3 SlideMove(Vector3 currentPos, Vector3 desiredDelta)
        {
            Vector3 totalMove = Vector3.zero;
            Vector3 remainingMove = desiredDelta;
            const int maxIterations = 3;

            for (int i = 0; i < maxIterations; i++)
            {
                if (remainingMove.sqrMagnitude < 0.0001f)
                    break;

                float moveLen = remainingMove.magnitude;
                Vector3 moveDir = remainingMove / moveLen;

                Vector3 top = currentPos + totalMove + Vector3.up * 1.5f;
                Vector3 bottom = currentPos + totalMove + Vector3.up * 0.2f;

                if (Physics.CapsuleCast(top, bottom, ConfigCapsuleRadius, moveDir, out RaycastHit hit, moveLen, ObstacleMask, QueryTriggerInteraction.Ignore))
                {
                    // Avancer jusqu'au point de contact (avec une petite marge)
                    float safeDistance = Mathf.Max(0f, hit.distance - 0.05f);
                    Vector3 safeMove = moveDir * safeDistance;
                    totalMove += safeMove;

                    // Calculer le mouvement restant projeté sur le plan de l'obstacle (sliding)
                    float leftoverDist = moveLen - hit.distance;
                    if (leftoverDist > 0.01f)
                    {
                        Vector3 leftoverDir = moveDir * leftoverDist;
                        remainingMove = Vector3.ProjectOnPlane(leftoverDir, hit.normal);
                    }
                    else
                    {
                        break;
                    }
                }
                else
                {
                    // Pas d'obstacle, on peut avancer complètement
                    totalMove += remainingMove;
                    break;
                }
            }

            return totalMove;
        }

        /// <summary>
        /// Finalise le dash en réactivant le mouvement et en mettant à jour les flags
        /// </summary>
        private void FinalizeDash()
        {
            isDashing = false;
            Debug.Log($"[DashCible] Dash finalisé, remainingChains={remainingChains}, slowMoApplied={slowMoApplied}");

            // Réactiver le mouvement normal
            if (fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }
        }

        private void ApplyOrRefreshSlowMo()
        {
            slowMoEndUnscaled = Time.unscaledTime + ConfigSlowMoTime;
            if (!slowMoApplied)
            {
                // S'assurer qu'on sauvegarde la bonne valeur (pas le hitstop)
                previousTimeScale = (Time.timeScale <= 0.01f) ? 1f : Time.timeScale;
                Time.timeScale = ConfigSlowMoScale;
                Time.fixedDeltaTime = 0.02f * Time.timeScale;
                slowMoApplied = true;
                Debug.Log($"[DashCible] SlowMo appliqué: timeScale={ConfigSlowMoScale}, previousTimeScale={previousTimeScale}, durée={ConfigSlowMoTime}s");
            }
            else
            {
                Debug.Log($"[DashCible] SlowMo rafraîchi: nouvelle fin dans {ConfigSlowMoTime}s");
            }
        }

        private void ClearSlowMo()
        {
            if (!slowMoApplied) return;

            // S'assurer qu'on restaure une valeur valide
            float targetTimeScale = (previousTimeScale <= 0.01f) ? 1f : previousTimeScale;
            Time.timeScale = targetTimeScale;
            Time.fixedDeltaTime = 0.02f * Time.timeScale;
            slowMoApplied = false;

            Debug.Log($"[DashCible] SlowMo terminé: timeScale restauré à {targetTimeScale}");

            // S'assurer que le mouvement est réactivé si on n'est plus en train de dasher
            if (!isDashing && fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }
        }

        private void EndChain()
        {
            chainActive = false;
            remainingChains = 0;
            nextAvailableTime = Time.time + ConfigCooldown;

            // S'assurer que le mouvement est réactivé
            if (fpsMovement != null)
            {
                fpsMovement.EnableMovement();
            }
        }

        private void OnDisable()
        {
            // Arrêter les coroutines en cours
            if (bounceCoroutine != null)
            {
                StopCoroutine(bounceCoroutine);
                bounceCoroutine = null;
            }

            // Restaurer le temps si hitstop ou slow-mo actif
            if (hitStopActive || slowMoApplied)
            {
                Time.timeScale = 1f;
                Time.fixedDeltaTime = 0.02f;
                hitStopActive = false;
            }
            if (slowMoApplied) ClearSlowMo();
            if (fpsMovement != null) fpsMovement.EnableMovement();
        }

        private void OnDestroy()
        {
            // Arrêter les coroutines en cours
            if (bounceCoroutine != null)
            {
                StopCoroutine(bounceCoroutine);
                bounceCoroutine = null;
            }

            // Restaurer le temps si hitstop ou slow-mo actif
            if (hitStopActive || slowMoApplied)
            {
                Time.timeScale = 1f;
                Time.fixedDeltaTime = 0.02f;
                hitStopActive = false;
            }
            if (slowMoApplied) ClearSlowMo();
            if (fpsMovement != null) fpsMovement.EnableMovement();
        }

        public int CountDash => ConfigCountDash;
        public float SlowMoTime => ConfigSlowMoTime;
        public float DistanceDash => ConfigDistanceDash;
        public float Cooldown => ConfigCooldown;

        public bool IsChainActive => chainActive;
        public int RemainingChains => chainActive ? Mathf.Clamp(remainingChains, 0, ConfigCountDash) : ConfigCountDash;
        public bool IsSlowMoActive => slowMoApplied;

        /// <summary>True si le cooldown global est en cours (après la fin du slow-mo)</summary>
        public bool IsCooldownActive => !chainActive && Time.time < nextAvailableTime;

        /// <summary>Progression du cooldown de 0 (début) à 1 (terminé)</summary>
        public float CooldownProgress => IsCooldownActive 
            ? 1f - ((nextAvailableTime - Time.time) / ConfigCooldown) 
            : 1f;

        private void TryStunElectricOnPath(Vector3 currentPos)
        {
            if (pathElectricStunned) return;
            Vector3 top = currentPos + Vector3.up * 1.5f;
            Vector3 bottom = currentPos + Vector3.up * 0.2f;
            int count = Physics.OverlapCapsuleNonAlloc(top, bottom, ConfigCapsuleRadius, OverlapBuffer, EnemyMask, QueryTriggerInteraction.Ignore);
            for (int i = 0; i < count; i++)
            {
                var col = OverlapBuffer[i];
                if (col == null) continue;
                var electric = col.GetComponentInParent<Ennemies.Effect.ElectricEnnemis>() ?? col.GetComponent<Ennemies.Effect.ElectricEnnemis>();
                if (electric == null) continue;

                var playerStun = GetComponent<PlayerStunAutoFire>() ?? gameObject.AddComponent<PlayerStunAutoFire>();
                if (electric.OverrideAutoFireInterval)
                    playerStun.ApplyStun(electric.StunDuration, electric.StunAutoFireInterval);
                else
                    playerStun.ApplyStun(electric.StunDuration);

                pathElectricStunned = true;
                break;
            }
        }

        /// <summary>
        /// Applique un hitstop en temps réel (pause du jeu) avant de continuer.
        /// </summary>
        private IEnumerator HitStopRealtime(float unscaledDuration, bool freezeTime)
        {
            if (unscaledDuration <= 0f)
                yield break;

            hitStopActive = true;

            // Sauvegarder l'état actuel du temps (s'assurer que c'est une valeur valide)
            float savedTimeScale = (Time.timeScale <= 0.01f) ? 1f : Time.timeScale;
            float savedFixedDeltaTime = Time.fixedDeltaTime;

            // Appliquer le freeze
            Time.timeScale = freezeTime ? 0f : 0.01f;
            Time.fixedDeltaTime = 0.02f * Time.timeScale;

            // Attendre en temps réel
            yield return new WaitForSecondsRealtime(unscaledDuration);

            // Restaurer l'état du temps (sauf si slow-mo est déjà appliqué, ce qui sera géré après)
            if (!slowMoApplied)
            {
                Time.timeScale = savedTimeScale;
                Time.fixedDeltaTime = 0.02f * savedTimeScale;
            }
            else
            {
                // Le slow-mo est déjà appliqué, restaurer sa valeur
                float targetTimeScale = (previousTimeScale <= 0.01f) ? 1f : previousTimeScale;
                Time.timeScale = ConfigSlowMoScale;
                Time.fixedDeltaTime = 0.02f * ConfigSlowMoScale;
            }

            hitStopActive = false;
        }

        /// <summary>
        /// Démarre la coroutine de rebond avec courbe.
        /// </summary>
        private void StartBounceImpulse(Vector3 dashDirection)
        {
            if (bounceCoroutine != null)
            {
                StopCoroutine(bounceCoroutine);
            }
            bounceCoroutine = StartCoroutine(ApplyBounceImpulseOverTime(dashDirection, CurrentBounce));
        }

        /// <summary>
        /// Applique l'impulsion de rebond sur une durée, pilotée par une courbe.
        /// La courbe contrôle la vitesse du rebond à chaque instant (Y=1 = vitesse max, Y=0 = pas de mouvement).
        /// </summary>
        private IEnumerator ApplyBounceImpulseOverTime(Vector3 dashDirection, BounceDefinition config)
        {
            if (config == null || config.force <= 0f)
            {
                bounceCoroutine = null;
                yield break;
            }

            Vector3 dir = ResolveBounceDirection(dashDirection, config);
            if (dir.sqrMagnitude <= 1e-4f)
            {
                bounceCoroutine = null;
                yield break;
            }

            // Si pas de durée ou pas de courbe, appliquer instantanément (comportement legacy)
            if (config.duration <= 0f || config.forceOverTime == null)
            {
                Vector3 instantImpulse = dir.normalized * config.force;
                ApplyMomentum(instantImpulse);
                bounceCoroutine = null;
                yield break;
            }

            // Application sur la durée avec la courbe
            // La courbe définit le multiplicateur de vitesse à chaque instant
            float elapsed = 0f;
            float duration = config.duration;
            Vector3 direction = dir.normalized;

            while (elapsed < duration)
            {
                // Calculer le facteur de la courbe (temps normalisé 0-1)
                float t = elapsed / duration;
                float curveValue = config.forceOverTime.Evaluate(t);

                // La courbe contrôle directement la vitesse à cet instant
                // force = vitesse de base, curveValue = multiplicateur de cette vitesse
                Vector3 velocity = direction * (config.force * curveValue);

                // Appliquer comme momentum (le système de momentum gère le déplacement)
                ApplyMomentum(velocity);

                elapsed += Time.deltaTime;
                yield return null;
            }

            bounceCoroutine = null;
        }

        /// <summary>
        /// Applique un momentum au joueur via fpsMovement ou fallback rb.
        /// </summary>
        private void ApplyMomentum(Vector3 momentum)
        {
            if (fpsMovement != null)
            {
                fpsMovement.ApplyExternalMomentum(momentum);
            }
            else if (rb != null)
            {
                rb.AddForce(momentum, ForceMode.VelocityChange);
            }
            else
            {
                transform.position += momentum * Time.deltaTime;
            }
        }

        private Vector3 ResolveBounceDirection(Vector3 fallbackDashDirection, BounceDefinition config)
        {
            Vector3 dir = config.directionIsLocal ? transform.TransformDirection(config.direction) : config.direction;
            if (dir.sqrMagnitude <= 1e-4f)
                dir = -fallbackDashDirection;
            if (dir.sqrMagnitude <= 1e-4f)
                return Vector3.up;
            return dir.normalized;
        }
    }
}

